// 精读语篇（阅读理解）
const READING_PASSAGES = [
  {level:'B2', title:'共享单车为何改变了城市', topic:'城市与交通', minutes:6,
    paragraphs:[
      {es:`Cuando en 2016 aparecieron las primeras bicicletas compartidas sin estación en las calles de Pekín, nadie imaginó la magnitud del fenómeno. Bastaba con escanear un código para desbloquear una bici y dejarla, al terminar el trayecto, en cualquier lugar permitido.`,
       zh:`2016年，当第一批无桩共享单车出现在北京街头时，没有人预料到这一现象的规模。只需扫一个码就能解锁一辆单车，行程结束后把它停在任何允许的地方即可。`},
      {es:`La promesa era sencilla y atractiva: resolver el llamado «último kilómetro», ese tramo incómodo entre la parada del transporte público y el destino final. Para millones de personas, supuso una alternativa real frente al taxi o a caminar bajo la lluvia.`,
       zh:`这个承诺简单而诱人：解决所谓的"最后一公里"，即公共交通站点与最终目的地之间那段别扭的路程。对数以百万计的人来说，它成了替代出租车或冒雨步行的一个真实选择。`},
      {es:`Sin embargo, el éxito trajo consigo problemas imprevistos. Las aceras se saturaron de vehículos amontonados, muchos en mal estado; los operadores, enfrascados en una guerra de precios, acumularon pérdidas millonarias; y las administraciones, pilladas por sorpresa, improvisaron normativas que a menudo llegaban tarde.`,
       zh:`然而，成功也带来了始料未及的问题。人行道被堆积如山的车辆占满，其中许多状况糟糕；运营商陷于价格战，累积了巨额亏损；而措手不及的行政部门临时制定规章，往往为时已晚。`},
      {es:`Lo que ocurrió después resulta más interesante que el auge inicial. Varias ciudades dejaron de limitarse a prohibir y empezaron a regular con criterios claros: cupos máximos por operador, obligación de retirar las bicis averiadas en plazos concretos y sistemas de aparcamiento señalizados. El resultado, lejos de ser perfecto, fue notablemente mejor.`,
       zh:`此后发生的事情比最初的繁荣更有意思。一些城市不再只满足于禁止，而是开始以明确的标准进行规范：单一运营商的最高投放配额、限期清理故障车辆的义务，以及划定的停车区域。结果虽远非完美，却明显更好。`},
      {es:`La lección quizá trascienda el caso concreto. Las innovaciones que irrumpen con fuerza suelen desbordar los marcos existentes, y la tentación de responder con prohibiciones es comprensible pero poco eficaz. Regular a tiempo, con datos y con margen para corregir, parece haber funcionado mejor que prohibir a destiempo.`,
       zh:`这个教训或许超出了具体案例本身。强势涌现的创新往往会冲垮既有的框架，而以禁令回应的诱惑可以理解，却收效甚微。及时且基于数据、并留有修正余地的规范，似乎比事后的禁止更有效。`}
    ],
    glossary:[
      {es:'el trayecto', zh:'行程、路段'},
      {es:'el último kilómetro', zh:'最后一公里'},
      {es:'el tramo', zh:'一段路程'},
      {es:'la acera', zh:'人行道'},
      {es:'amontonado', zh:'堆积的'},
      {es:'enfrascarse en', zh:'埋头于、陷入'},
      {es:'millonario', zh:'数以百万计的'},
      {es:'improvisar', zh:'临时应付、即兴而为'},
      {es:'el cupo', zh:'配额'},
      {es:'averiado', zh:'故障的、损坏的'},
      {es:'señalizado', zh:'有标识的'},
      {es:'trascender', zh:'超越'},
      {es:'irrumpir', zh:'闯入、涌现'},
      {es:'desbordar', zh:'溢出、冲垮'},
      {es:'a destiempo', zh:'不合时宜地、为时已晚'}
    ],
    structures:[
      {es:`Bastaba con escanear un código para desbloquear una bici y dejarla, al terminar el trayecto, en cualquier lugar permitido.`,
       note:`bastar con + 不定式，表示「只需……就够了」。中间的 al terminar el trayecto 是插入的时间状语，插在动词和它的宾语补足语之间，是西语常见的「分隔」手法，翻译时要还原语序。`},
      {es:`los operadores, enfrascados en una guerra de precios, acumularon pérdidas millonarias`,
       note:`enfrascados en… 是过去分词短语作后置定语（相当于一个省略了 which were 的定语从句）。这类结构在书面语里极为常见，能让句子更紧凑，但要注意分词的性与数必须和中心词一致。`},
      {es:`El resultado, lejos de ser perfecto, fue notablemente mejor.`,
       note:`lejos de + 不定式 ＝「远非、不但没有」。这里同样是用逗号插入，起让步作用。注意它和表示距离的 lejos de（远离）要区分。`},
      {es:`Regular a tiempo, con datos y con margen para corregir, parece haber funcionado mejor que prohibir a destiempo.`,
       note:`主语是一个不定式短语（Regular a tiempo…），谓语 parece 用第三人称单数。haber funcionado 是完成不定式，表示「（到当时为止）已经奏效」，与 parece 搭配表示推测过去。`}
    ],
    questions:[
      {q:'¿Qué problema resolvían las bicicletas compartidas?', a:'El llamado «último kilómetro» entre el transporte público y el destino final.'},
      {q:'¿Qué problemas trajo el éxito?', a:'Aceras saturadas, operadores con pérdidas millonarias y normativas improvisadas.'},
      {q:'¿Qué cambio de enfoque se produjo después?', a:'Las ciudades pasaron de prohibir a regular con criterios claros.'},
      {q:'¿Cuál es la lección general del texto?', a:'Que regular a tiempo con datos y margen de corrección funciona mejor que prohibir a destiempo.'}
    ]
  },
  {level:'B2', title:'为什么我们记不住读过的东西', topic:'认知与学习', minutes:6,
    paragraphs:[
      {es:`Pocas sensaciones resultan tan frustrantes como terminar un libro y descubrir que apenas recordamos su contenido. La reacción habitual es culpar a la memoria, pero el problema suele estar en cómo leemos, no en cuánto retenemos.`,
       zh:`很少有哪种感受比读完一本书却发现自己几乎记不住内容更令人沮丧。通常的反应是怪罪记忆力，但问题往往出在我们怎么读，而不是我们能记住多少。`},
      {es:`La lectura pasiva —esa que consiste en deslizar la vista por las líneas mientras la mente divaga— produce una ilusión de comprensión. Creemos haber entendido porque las frases nos resultan familiares, aunque no hayamos reconstruido su significado.`,
       zh:`被动阅读——也就是目光在字行间滑过、思绪却在游荡的那种——会产生一种「懂了」的错觉。我们以为自己理解了，因为这些句子读起来熟悉，尽管我们并没有重建它们的含义。`},
      {es:`La investigación sobre aprendizaje señala que la comprensión se consolida cuando el lector genera algo: una pregunta, un resumen, un ejemplo propio. Dicho de otro modo, recordamos lo que elaboramos, no lo que simplemente recibimos.`,
       zh:`关于学习的研究指出，当读者产出某些东西时，理解才会巩固：一个问题、一段摘要、一个自己的例子。换句话说，我们记住的是自己加工过的东西，而不是仅仅接收到的。`},
      {es:`De ahí que las técnicas más eficaces resulten, paradójicamente, las más incómodas: cerrar el libro y tratar de explicar lo leído, escribir preguntas que el texto responde o compararlo con algo que ya sabíamos. Todas exigen un esfuerzo que la lectura cómoda evita.`,
       zh:`因此，最有效的技巧反而悖论式地是最不舒服的：合上书试着复述所读内容、写下文本能回答的问题，或者把它与已知的东西作比较。它们都要求付出一种舒适阅读所回避的努力。`},
      {es:`Esto no significa que leer por placer sea una pérdida de tiempo. Significa que, si el objetivo es aprender, conviene interrumpir la lectura de vez en cuando y hacer algo con ella. La incomodidad, en este caso, no es un síntoma de que algo va mal: es la señal de que algo está ocurriendo.`,
       zh:`这并不意味着为消遣而读书是浪费时间。它的意思是，如果目标是学习，就该时不时打断阅读，拿它做点什么。在这种情况下，不适感并不是出了问题，而是正在发生什么的信号。`}
    ],
    glossary:[
      {es:'frustrante', zh:'令人沮丧的'},
      {es:'retener', zh:'记住、保持'},
      {es:'divagar', zh:'走神、漫谈'},
      {es:'la ilusión de comprensión', zh:'理解的错觉'},
      {es:'reconstruir', zh:'重建'},
      {es:'consolidarse', zh:'巩固'},
      {es:'elaborar', zh:'加工、制作'},
      {es:'paradójicamente', zh:'悖论式地'},
      {es:'de ahí que', zh:'因此（+虚拟式）'},
      {es:'exigir', zh:'要求'},
      {es:'el síntoma', zh:'症状、信号'},
      {es:'conviene', zh:'宜、应当'}
    ],
    structures:[
      {es:`Pocas sensaciones resultan tan frustrantes como terminar un libro y descubrir que apenas recordamos su contenido.`,
       note:`tan… como… 表示同级比较。这里主语 Pocas sensaciones 与后面的不定式短语作对比项。注意 apenas 在这里是「几乎不」，不是「刚刚」。`},
      {es:`Creemos haber entendido porque las frases nos resultan familiares, aunque no hayamos reconstruido su significado.`,
       note:`haber entendido 是完成不定式，作 creer 的直接宾语，表示「认为自己已经懂了」。aunque + 虚拟式（hayamos）表示让步且说话人对该事实持保留态度。`},
      {es:`De ahí que las técnicas más eficaces resulten, paradójicamente, las más incómodas.`,
       note:`de ahí que 后面必须接虚拟式（resulten），这是固定要求。paradójicamente 用逗号插入作评注性状语。`},
      {es:`La incomodidad, en este caso, no es un síntoma de que algo va mal: es la señal de que algo está ocurriendo.`,
       note:`un síntoma de que 后面用陈述式（va mal），因为这是说话人认定的事实；如果换成 no es que…，则需用虚拟式。冒号后的 es la señal de que 起对比强调作用。`}
    ],
    questions:[
      {q:'¿Por qué la lectura pasiva resulta engañosa?', a:'Porque produce una ilusión de comprensión: las frases resultan familiares sin que se reconstruya el significado.'},
      {q:'¿Qué dice la investigación sobre la comprensión?', a:'Que se consolida cuando el lector genera algo propio.'},
      {q:'Cite dos técnicas eficaces mencionadas.', a:'Cerrar el libro y explicar lo leído; escribir preguntas que el texto responde.'},
      {q:'¿Cómo interpreta el texto la incomodidad?', a:'Como señal de que algo está ocurriendo, no como síntoma de que algo va mal.'}
    ]
  },
  {level:'B2', title:'城市的噪音与健康', topic:'健康与环境', minutes:6,
    paragraphs:[
      {es:`El ruido del tráfico rara vez se percibe como un problema sanitario. Sin embargo, la Organización Mundial de la Salud lo sitúa entre los principales riesgos ambientales para la salud, por detrás únicamente de la contaminación del aire.`,
       zh:`交通噪音很少被视为一个健康问题。然而，世界卫生组织将其列为环境健康的主要风险之一，仅次于空气污染。`},
      {es:`El mecanismo no es tan intuitivo como parece. El oído capta el sonido, pero es el cerebro quien lo interpreta como amenaza; esa interpretación activa respuestas de estrés que, mantenidas durante años, afectan al sistema cardiovascular.`,
       zh:`其机制并不像看上去那么直观。耳朵捕捉声音，但把它解读为威胁的是大脑；这种解读会激活应激反应，而长期持续便会影响心血管系统。`},
      {es:`Lo llamativo es que los efectos se producen incluso durante el sueño. Aunque quien duerme no recuerde haberse despertado, el organismo registra cada subida de intensidad y responde con microdespertares que fragmentan el descanso sin dejar rastro consciente.`,
       zh:`值得注意的是，这些影响甚至在睡眠中也发生。即便睡着的人不记得自己醒过，身体仍会记录每一次强度的升高，并以微觉醒作出反应，在不留下意识痕迹的情况下使休息变得破碎。`},
      {es:`Por eso los expertos insisten en que las medidas deben centrarse en la fuente y no solo en el aislamiento acústico de las viviendas. Aislar ayuda, desde luego, pero traslada el problema a quien no puede permitirse reformar su casa.`,
       zh:`因此专家坚持认为，措施应当着眼于源头，而不只是住宅的隔音。隔音固然有帮助，但它把问题转嫁给了无力改造住房的人。`},
      {es:`Las soluciones que han dado mejores resultados combinan varias capas: asfalto fonoabsorbente, límites de velocidad nocturnos, peatonalización de calles residenciales y planificación urbana que evite situar hospitales y escuelas junto a vías rápidas.`,
       zh:`效果最好的方案结合了多个层面：吸音沥青、夜间限速、住宅街道步行化，以及避免把医院和学校设在快速路旁的城市规划。`}
    ],
    glossary:[
      {es:'el ruido', zh:'噪音'},
      {es:'sanitario', zh:'卫生的、健康的'},
      {es:'la amenaza', zh:'威胁'},
      {es:'cardiovascular', zh:'心血管的'},
      {es:'llamativo', zh:'引人注意的'},
      {es:'el microdespertar', zh:'微觉醒'},
      {es:'fragmentar', zh:'使破碎'},
      {es:'el aislamiento acústico', zh:'隔音'},
      {es:'trasladar', zh:'转移'},
      {es:'fonoabsorbente', zh:'吸音的'},
      {es:'la vía rápida', zh:'快速路'},
      {es:'la capa', zh:'层面、层'}
    ],
    structures:[
      {es:`la Organización Mundial de la Salud lo sitúa entre los principales riesgos ambientales para la salud, por detrás únicamente de la contaminación del aire.`,
       note:`lo sitúa 中的 lo 是直接宾语代词，前指 el ruido。por detrás únicamente de… 表示排名位置，「仅次于」。`},
      {es:`es el cerebro quien lo interpreta como amenaza`,
       note:`es… quien… 是强调句式，用于强调主语（el cerebro）。注意 quien 与先行词单复数一致；此处也可用 el que。`},
      {es:`Aunque quien duerme no recuerde haberse despertado, el organismo registra cada subida de intensidad.`,
       note:`quien duerme 是名词性关系从句作主语，意为「睡着的那个人」。recuerde 用虚拟式，因为 aunque 在此表让步且对事实不作断言。haberse despertado 是完成不定式的自复形式。`},
      {es:`Aislar ayuda, desde luego, pero traslada el problema a quien no puede permitirse reformar su casa.`,
       note:`Aislar 是名词化不定式作主语。a quien no puede… 中 quien 是关系代词，前面带前置词 a，表「转嫁给（某个）无力……的人」。`}
    ],
    questions:[
      {q:'¿Qué lugar ocupa el ruido entre los riesgos ambientales según la OMS?', a:'El segundo, solo por detrás de la contaminación del aire.'},
      {q:'¿Dónde se produce realmente la interpretación del sonido como amenaza?', a:'En el cerebro, no en el oído.'},
      {q:'¿Por qué el ruido afecta incluso a quien no se despierta?', a:'Porque el organismo registra las subidas de intensidad y responde con microdespertares.'},
      {q:'¿Por qué los expertos prefieren actuar sobre la fuente?', a:'Porque el aislamiento traslada el problema a quien no puede costearlo.'}
    ]
  },
  {level:'B2', title:'远程办公重塑了什么', topic:'工作与社会', minutes:6,
    paragraphs:[
      {es:`Cuando en 2020 millones de personas trasladaron su escritorio a casa, la mayoría lo interpretó como una medida temporal. Cinco años después, resulta evidente que aquel paréntesis alteró de forma duradera la manera en que concebimos el trabajo.`,
       zh:`2020年，当数百万人把办公桌搬回家时，大多数人把它理解为一项临时措施。五年之后，显而易见，那段"插曲"持久地改变了我们理解工作的方式。`},
      {es:`La primera consecuencia fue la desaparición de la frontera física entre el empleo y la vida privada. Ya no había trayecto que marcara el inicio y el final de la jornada; el trayecto pasó a ser mental, y no todo el mundo supo trazarlo.`,
       zh:`第一个后果是工作与私人生活之间物理边界消失。不再有通勤来标记一天工作的开始与结束；这段"路程"变成了心理上的，而并非所有人都懂得如何划定它。`},
      {es:`Las empresas descubrieron, además, que la productividad dependía menos de las horas de presencia de lo que se creía. Pero también comprobaron algo incómodo: las ideas que surgen de una conversación casual en el pasillo no se reproducen por videollamada.`,
       zh:`企业还发现，生产效率对比出勤时长的依赖比人们以为的要小。但同时也验证了一件令人不适的事：走廊里闲聊时闪现的想法，无法通过视频会议复制。`},
      {es:`De ahí que los modelos híbridos se hayan impuesto como compromiso. No obstante, el consenso es más aparente que real: cada organización los aplica a su manera, y muchas lo hacen guiadas por la desconfianza más que por la evidencia.`,
       zh:`因此在折中之下，混合模式成为主流。然而这种共识更多是表面上的：每个组织各按自己的方式实施，而许多组织的出发点是不信任，而不是证据。`},
      {es:`Lo que está en juego, en definitiva, no es dónde trabajamos, sino quién decide dónde trabajamos y con qué criterios. Esa pregunta, que durante décadas ni siquiera se planteaba, es probablemente el cambio más profundo de todos.`,
       zh:`归根结底，真正的问题不在于我们在哪里工作，而在于谁决定我们在哪里工作、依据什么标准。这个问题在几十年间甚至不曾被提出，而它或许才是最深刻的改变。`}
    ],
    glossary:[
      {es:'el paréntesis', zh:'插曲、间断'},
      {es:'duradero', zh:'持久的'},
      {es:'concebir', zh:'构想、理解'},
      {es:'la jornada', zh:'工作日'},
      {es:'trazar', zh:'划定、描画'},
      {es:'la presencia', zh:'出勤、在场'},
      {es:'comprobar', zh:'验证'},
      {es:'imponerse', zh:'成为主流、占上风'},
      {es:'aparente', zh:'表面的'},
      {es:'estar en juego', zh:'关键在于、攸关'},
      {es:'el criterio', zh:'标准'}
    ],
    structures:[
      {es:`la productividad dependía menos de las horas de presencia de lo que se creía`,
       note:`menos… de lo que + 动词，表示「比人们所认为的……更少」。de lo que 引出比较的基准，其中 lo 指代前面的比较内容。`},
      {es:`De ahí que los modelos híbridos se hayan impuesto como compromiso.`,
       note:`de ahí que 后必须用虚拟式（hayan impuesto）。hayan impuesto 是自复动词 imponerse 的现在完成虚拟式，表示到目前已经完成的变化。`},
      {es:`el consenso es más aparente que real`,
       note:`más… que… 比较结构。注意 aparente 在此意为「表面的」，而非「明显的」——这是个常见的歧义词。`},
      {es:`Esa pregunta, que durante décadas ni siquiera se planteaba, es probablemente el cambio más profundo de todos.`,
       note:`逗号之间的 que 引导非限定性定语从句，起补充说明作用。注意谓语是 es，主语是 Esa pregunta，从句插在中间是西语常见结构。`}
    ],
    questions:[
      {q:'¿Qué frontera desapareció con el teletrabajo?', a:'La frontera física entre el empleo y la vida privada.'},
      {q:'¿Qué cosa incómoda comprobaron las empresas?', a:'Que las ideas de las conversaciones casuales no se reproducen por videollamada.'},
      {q:'¿Qué crítica hace el texto a los modelos híbridos?', a:'Que se aplican guiados por la desconfianza más que por la evidencia.'},
      {q:'¿Cuál es, según el texto, el cambio más profundo?', a:'La pregunta sobre quién decide dónde trabajamos y con qué criterios.'}
    ]
  },
  {level:'B2', title:'食品浪费为何难以解决', topic:'经济与环境', minutes:6,
    paragraphs:[
      {es:`Se calcula que un tercio de los alimentos producidos en el mundo termina en la basura. La cifra resulta escandalosa en un planeta donde millones de personas pasan hambre, y sin embargo apenas ha cambiado en la última década.`,
       zh:`据估算，全球生产的食物有三分之一最终进了垃圾桶。在这个数以百万计的人挨饿的星球上，这个数字令人震惊，然而在过去十年里它几乎没有变化。`},
      {es:`La explicación habitual apunta al consumidor: compramos de más, olvidamos lo que guardamos en la nevera y desechamos productos cuya apariencia no nos convence. Todo eso es cierto, pero solo explica una parte del problema.`,
       zh:`常见的解释指向消费者：我们买得太多、忘了冰箱里存着什么，还丢弃那些外观不合心意的产品。这些都是事实，但只能解释问题的一部分。`},
      {es:`Buena parte del desperdicio ocurre antes de que el alimento llegue al supermercado. Las normas estéticas, los calendarios de entrega y los contratos con cláusulas de devolución empujan a los productores a descartar cosechas enteras que son perfectamente comestibles.`,
       zh:`相当一部分浪费发生在食物到达超市之前。外观标准、交货时间表，以及带有退货条款的合同，都在推动生产者把整季完全可食用的收成当作废品处理。`},
      {es:`A esto se suma que tirar comida rara vez tiene consecuencias. El coste de desecharla queda diluido en la cadena y no aparece en ninguna factura, de modo que nadie tiene un incentivo claro para evitarlo.`,
       zh:`此外，扔掉食物很少带来后果。丢弃的成本被稀释在整条产业链中，不出现在任何一张账单上，因此没有人有明确的动力去避免它。`},
      {es:`Las iniciativas que han funcionado comparten un rasgo: hacen visible el desperdicio. Cuando un ayuntamiento pesa y publica los residuos orgánicos de cada barrio, o cuando un supermercado dona lo que no vende con trazabilidad, la conducta cambia sin necesidad de grandes discursos.`,
       zh:`那些见效的举措有一个共同特点：让浪费变得可见。当某个市政府称重并公布各街区的厨余垃圾，或者超市可追溯地捐赠未售出的商品时，行为就改变了，无需宏大的说教。`}
    ],
    glossary:[
      {es:'el desperdicio', zh:'浪费'},
      {es:'escandaloso', zh:'令人震惊的'},
      {es:'desechar', zh:'丢弃'},
      {es:'la apariencia', zh:'外观'},
      {es:'la nevera', zh:'冰箱'},
      {es:'estético', zh:'外观上的、审美的'},
      {es:'la cláusula', zh:'条款'},
      {es:'descartar', zh:'淘汰、丢弃'},
      {es:'la cosecha', zh:'收成'},
      {es:'comestible', zh:'可食用的'},
      {es:'diluido', zh:'被稀释的'},
      {es:'la trazabilidad', zh:'可追溯性'}
    ],
    structures:[
      {es:`un planeta donde millones de personas pasan hambre`,
       note:`donde 在此引导关系从句修饰 planeta，相当于 en el que。表示地点的先行词后常用 donde，比 en el que 更简洁。`},
      {es:`desechamos productos cuya apariencia no nos convence`,
       note:`cuyo 是关系形容词，表示所属关系，性数随其后名词（apariencia）变化，而非随先行词。此处 cuya apariencia = la apariencia de los cuales。`},
      {es:`A esto se suma que tirar comida rara vez tiene consecuencias.`,
       note:`A esto se suma que… 意为「此外还有……」。tirar comida 是名词化不定式作从句主语，谓语用单数 tiene。`},
      {es:`de modo que nadie tiene un incentivo claro para evitarlo`,
       note:`de modo que 表示结果。注意若表示目的（「以便」）则需用虚拟式；此处表示实际结果，故用陈述式。`}
    ],
    questions:[
      {q:'¿Qué proporción de los alimentos producidos se desperdicia?', a:'Un tercio.'},
      {q:'¿Dónde ocurre buena parte del desperdicio?', a:'Antes de que el alimento llegue al supermercado.'},
      {q:'¿Por qué tirar comida rara vez tiene consecuencias?', a:'Porque el coste queda diluido en la cadena y no aparece en ninguna factura.'},
      {q:'¿Qué rasgo comparten las iniciativas que funcionan?', a:'Hacen visible el desperdicio.'}
    ]
  },
  {level:'C1', title:'论说理的限度', topic:'思想与社会', minutes:8,
    paragraphs:[
      {es:`Existe una convicción ampliamente extendida según la cual, si se expone un argumento con suficiente claridad, cualquier interlocutor razonable acabará aceptándolo. La experiencia, por desgracia, desmiente esa expectativa con una frecuencia desconcertante.`,
       zh:`有一种广泛流传的信念认为，只要把论点讲得足够清楚，任何通情达理的对话者最终都会接受。遗憾的是，经验以令人困惑的频率否定了这一预期。`},
      {es:`Ello no se debe a que la gente sea estúpida —esa conclusión, además de soberbia, es falsa—, sino a que los juicios humanos rara vez se apoyan solo en razones. Se asientan también en la identidad, en el grupo al que uno pertenece y en el coste emocional que supone desdecirse.`,
       zh:`这并非因为人们愚蠢——这个结论既傲慢又错误——而是因为人的判断很少只建立在理由之上。它们还建立在身份、所属群体，以及改口所需付出的情感代价之上。`},
      {es:`Cuando una creencia forma parte de lo que uno es, rebatirla no se percibe como una corrección sino como una agresión. Y ante una agresión, la respuesta instintiva no es reconsiderar la propia postura, sino reforzarla.`,
       zh:`当一种信念构成"自己是谁"的一部分时，反驳它不会被感受为纠正，而被感受为攻击。而面对攻击，本能的反应不是重新考虑自己的立场，而是强化它。`},
      {es:`De ahí que insistir en los datos, por sólidos que sean, resulte a menudo contraproducente. No porque los datos carezcan de valor, sino porque se presentan en el terreno equivocado: el de la lógica, cuando la discusión se libra en el de la pertenencia.`,
       zh:`因此在数据上纠缠，无论数据多扎实，往往适得其反。不是因为数据没有价值，而是因为它们被呈现在错误的场域：逻辑的场域，而争论实际发生在归属感的场域。`},
      {es:`Quienes han estudiado el fenómeno coinciden en que el camino más eficaz es indirecto: preguntar antes que afirmar, admitir los propios límites, y sobre todo dejar al otro una salida digna. Nadie cambia de opinión si el cambio equivale a una humillación.`,
       zh:`研究这一现象的人一致认为，最有效的路径是间接的：先问再断言，承认自身的局限，尤其是给对方留一条体面的退路。如果改变立场等于受辱，没有人会改变。`},
      {es:`Nada de esto convierte la razón en algo prescindible. Significa, más bien, que la razón es una herramienta poderosa pero frágil, y que ignorar las condiciones en que se la recibe es la manera más segura de desperdiciarla.`,
       zh:`这一切并没有使理性变得可有可无。它更意味着，理性是一种强大却脆弱的工具，而忽视它被接受时所处的条件，是最稳妥的浪费它的方式。`}
    ],
    glossary:[
      {es:'la convicción', zh:'信念'},
      {es:'desmentir', zh:'否定、驳斥'},
      {es:'desconcertante', zh:'令人困惑的'},
      {es:'soberbia', zh:'傲慢'},
      {es:'asentarse en', zh:'建立在'},
      {es:'desdecirse', zh:'改口、收回前言'},
      {es:'rebatir', zh:'反驳'},
      {es:'instintivo', zh:'本能的'},
      {es:'contraproducente', zh:'适得其反的'},
      {es:'carecer de', zh:'缺乏'},
      {es:'la pertenencia', zh:'归属'},
      {es:'libarse', zh:'进行（战斗、争论）'},
      {es:'prescindible', zh:'可有可无的'},
      {es:'frágil', zh:'脆弱的'}
    ],
    structures:[
      {es:`según la cual, si se expone un argumento con suficiente claridad, cualquier interlocutor razonable acabará aceptándolo`,
       note:`según la cual 是「前置词 + 关系代词」结构，la cual 指代前面的 convicción。这类结构比 según que 更正式，且能避免歧义。`},
      {es:`Ello no se debe a que la gente sea estúpida, sino a que los juicios humanos rara vez se apoyan solo en razones.`,
       note:`no… sino… 表「不是……而是……」。关键点：no se debe a que 后用虚拟式（sea），因为它否定了一个原因；而肯定部分 a que los juicios… se apoyan 用陈述式。这是西语虚拟式最易错的地方之一。`},
      {es:`por sólidos que sean`,
       note:`por + 形容词 + que + 虚拟式，表示让步「无论多么……」。形容词需与主语保持性数一致（此处与 los datos 一致为阳性复数）。`},
      {es:`cuando la discusión se libra en el de la pertenencia`,
       note:`el de la pertenencia 中 el 是代词，替代前文提到的 terreno，避免重复。这种「定冠词 + de」的替代手法在书面语中很常见。`},
      {es:`Nadie cambia de opinión si el cambio equivale a una humillación.`,
       note:`注意 nadie 作主语时后面若有形容词，需加 no 还是保持否定？此处无形容词，直接否定。若说 nadie inteligente cambia…，则不能用 no。`}
    ],
    questions:[
      {q:'¿Qué convicción extendida cuestiona el texto?', a:'Que basta exponer un argumento con claridad para que cualquiera lo acepte.'},
      {q:'¿Por qué no se acepta una refutación, según el texto?', a:'Porque cuando la creencia forma parte de la identidad, se percibe como agresión.'},
      {q:'¿Por qué insistir en los datos puede ser contraproducente?', a:'Porque se presentan en el terreno de la lógica cuando la discusión se libra en el de la pertenencia.'},
      {q:'¿Qué camino indirecto se propone?', a:'Preguntar antes que afirmar, admitir los propios límites y dejar al otro una salida digna.'},
      {q:'¿Cómo describe el texto a la razón?', a:'Como una herramienta poderosa pero frágil.'}
    ]
  },
  {level:'C1', title:'算法时代的注意力经济', topic:'科技与社会', minutes:8,
    paragraphs:[
      {es:`Durante buena parte del siglo XX, los medios competían por el tiempo libre de las personas. Hoy la competencia es de otra naturaleza: no se disputa únicamente la atención, sino la capacidad misma de sostenerla.`,
       zh:`在20世纪的大部分时间里，媒体争夺的是人们的闲暇时间。今天这种竞争性质不同：争夺的不只是注意力，而是维持注意力的能力本身。`},
      {es:`El modelo de negocio subyacente explica por qué. Cuando los ingresos dependen de la publicidad, cada segundo adicional de permanencia se traduce en dinero; en consecuencia, los sistemas se optimizan para prolongar la sesión, no para satisfacer una necesidad concreta del usuario.`,
       zh:`其背后的商业模式解释了原因。当收入依赖广告时，每多停留一秒都会转化为金钱；因此，系统被优化为延长会话，而不是满足用户的某个具体需求。`},
      {es:`Cabe objetar que el usuario elige libremente. Pero esa libertad es más formal que efectiva cuando el diseño ha sido concebido por equipos que estudian, con enorme sofisticación, cómo anticipar y vencer la resistencia del usuario.`,
       zh:`可以反驳说用户是自由选择的。但当设计是由极其精细地研究如何预判并克服用户抵触的团队构想出来的时候，这种自由更多是形式上的，而非实质上的。`},
      {es:`Lo más inquietante no es el tiempo consumido, sino el hábito que se instala. La atención sostenida, como cualquier capacidad, se atrofia si no se ejercita; y una sociedad que la ha debilitado encuentra dificultades crecientes para leer, deliberar y sostener un argumento largo.`,
       zh:`最令人不安的不是被消耗的时间，而是被养成的习惯。持续注意力如同任何能力，不锻炼就会萎缩；而一个削弱了它的社会，在阅读、审议和维持长篇论证方面会遇到越来越大的困难。`},
      {es:`Frente a ello se han ensayado respuestas de distinto signo. Unas apuestan por la regulación —límites a la publicidad dirigida a menores, auditorías de los sistemas de recomendación—; otras confían en la pedagogía, enseñando a reconocer las técnicas de captación.`,
       zh:`对此人们尝试了不同方向的应对。有的主张监管——限制针对未成年人的定向广告、对推荐系统进行审计；有的信任教育，教人识别这些抓取注意力的手法。`},
      {es:`Ninguna de las dos basta por separado, y conviene desconfiar de quien promete una solución única. Lo que sí parece claro es que dejar el problema exclusivamente en manos de quien lucra con él no ha funcionado, y difícilmente funcionará.`,
       zh:`两者单独都不够，而且应当警惕那些许诺唯一解决方案的人。可以明确的是，把问题完全交给从中获利的一方，这一做法至今没有奏效，也很难奏效。`}
    ],
    glossary:[
      {es:'disputar', zh:'争夺'},
      {es:'la atención', zh:'注意力'},
      {es:'sostener', zh:'维持'},
      {es:'subyacente', zh:'背后的、潜在的'},
      {es:'la permanencia', zh:'停留'},
      {es:'optimizar', zh:'优化'},
      {es:'prolongar', zh:'延长'},
      {es:'objetar', zh:'提出反对'},
      {es:'la sofisticación', zh:'精细复杂'},
      {es:'vencer la resistencia', zh:'克服抵触'},
      {es:'inquietante', zh:'令人不安的'},
      {es:'atrofiarse', zh:'萎缩'},
      {es:'deliberar', zh:'审议、商议'},
      {es:'ensayar', zh:'尝试'},
      {es:'la captación', zh:'获取、吸引'},
      {es:'lucrar', zh:'获利'}
    ],
    structures:[
      {es:`no se disputa únicamente la atención, sino la capacidad misma de sostenerla`,
       note:`no… sino… 结构；注意 sino 后接名词短语。misma 用于加强语气，强调「……本身」。sostenerla 中的 la 回指 la atención。`},
      {es:`cada segundo adicional de permanencia se traduce en dinero`,
       note:`traducirse en 意为「转化为」。注意 traducir 与 traducirse en 的含义差别：后者是「体现为、导致」。`},
      {es:`esa libertad es más formal que efectiva cuando el diseño ha sido concebido por equipos que estudian cómo anticipar y vencer la resistencia del usuario`,
       note:`más… que… 比较；cuando 引导时间状语从句。ha sido concebido 是被动语态的现在完成时，施动者由 por 引出。`},
      {es:`La atención sostenida, como cualquier capacidad, se atrofia si no se ejercita.`,
       note:`como cualquier capacidad 是插入的比较状语。se atrofia 与 se ejercita 均为自复被动（无人称）用法，不指出施动者。`},
      {es:`dejar el problema exclusivamente en manos de quien lucra con él no ha funcionado`,
       note:`不定式短语作主语，谓语用第三人称单数。quien lucra 是名词性关系从句，作 en manos de 的宾语；él 回指 el problema。`}
    ],
    questions:[
      {q:'¿En qué se diferencia la competencia actual de la del siglo XX?', a:'Antes se disputaba el tiempo libre; ahora se disputa la capacidad misma de sostener la atención.'},
      {q:'¿Por qué los sistemas se optimizan para prolongar la sesión?', a:'Porque los ingresos dependen de la publicidad y cada segundo adicional se traduce en dinero.'},
      {q:'¿Por qué la libertad de elección es «más formal que efectiva»?', a:'Porque el diseño ha sido concebido para anticipar y vencer la resistencia del usuario.'},
      {q:'¿Qué consecuencia social señala el texto?', a:'Dificultades crecientes para leer, deliberar y sostener un argumento largo.'},
      {q:'¿Qué dos tipos de respuesta se han ensayado?', a:'La regulación y la pedagogía.'}
    ]
  },
  {level:'C1', title:'专业知识的信任危机', topic:'社会与科学', minutes:8,
    paragraphs:[
      {es:`La desconfianza hacia los expertos no es un fenómeno nuevo; lo que resulta novedoso es su generalización. Antes se dudaba de un especialista concreto por motivos concretos; hoy se duda del conocimiento especializado como tal.`,
       zh:`对专家的不信任并非新现象；新颖之处在于它的普遍化。以前人们因具体缘由怀疑某位具体的专家；如今人们怀疑的是专业知识本身。`},
      {es:`Sería cómodo atribuirlo a la ignorancia, pero semejante explicación no resiste el menor análisis. Algunas de las corrientes más escépticas hacia la ciencia surgen precisamente entre personas con formación universitaria, y no por casualidad.`,
       zh:`把它归因于无知会很省事，但这种解释经不起任何推敲。一些对科学最持怀疑态度的思潮恰恰出现在受过大学教育的人群中，而这并非偶然。`},
      {es:`Una parte de la explicación reside en los propios expertos. Durante décadas, la autoridad científica se presentó como incuestionable, y cuando esa autoridad se equivocó —como inevitablemente ocurre en toda empresa humana—, el coste en credibilidad fue muy superior al del error mismo.`,
       zh:`一部分解释在于专家自身。几十年来，科学权威被呈现为不容置疑，而当这种权威出错时——正如在一切人类事业中不可避免的那样——其在公信力上的代价远超过错误本身。`},
      {es:`A ello se añade la velocidad de la información. Un hallazgo preliminar, publicado con las cautelas propias del caso, circula por las redes despojado de esas cautelas y convertido en titular categórico; cuando semanas después se matiza, la rectificación no alcanza a quienes leyeron el titular.`,
       zh:`除此之外还有信息传播的速度。一项带有应有审慎措辞发表的初步发现，在网络上传播时被剥离了那些审慎，变成了斩钉截铁的标题；几周后加以限定说明时，更正却传不到当初读标题的那些人那里。`},
      {es:`Restablecer la confianza exigiría, según quienes estudian el problema, dos cosas difíciles de aceptar: que los expertos reconozcan públicamente el alcance de su incertidumbre, y que los ciudadanos acepten convivir con ella. Ninguna de las dos se consigue con campañas de imagen.`,
       zh:`据研究这一问题的人说，重建信任需要接受两件难以接受的事：专家要公开承认其不确定性的范围，而公民要接受与这种不确定性共存。这两件事都不是靠形象宣传能做到的。`},
      {es:`Quizá el malentendido de fondo consista en haber confundido la ciencia con un catálogo de certezas. No lo es: es un método para reducir el error, y su virtud no radica en no equivocarse, sino en corregirse.`,
       zh:`也许根本的误解在于把科学当成了一本确定性的目录。它不是：它是一种减少错误的方法，其优点不在于不犯错，而在于能自我修正。`}
    ],
    glossary:[
      {es:'la desconfianza', zh:'不信任'},
      {es:'la generalización', zh:'普遍化'},
      {es:'el conocimiento especializado', zh:'专业知识'},
      {es:'la ignorancia', zh:'无知'},
      {es:'resistir el análisis', zh:'经得起分析'},
      {es:'escéptico', zh:'怀疑的'},
      {es:'residir en', zh:'在于'},
      {es:'incuestionable', zh:'不容置疑的'},
      {es:'la credibilidad', zh:'公信力'},
      {es:'las cautelas', zh:'审慎、谨慎措辞'},
      {es:'despojado de', zh:'被剥离了'},
      {es:'categórico', zh:'斩钉截铁的'},
      {es:'la rectificación', zh:'更正'},
      {es:'restablecer', zh:'重建'},
      {es:'la incertidumbre', zh:'不确定性'},
      {es:'radicar en', zh:'在于'}
    ],
    structures:[
      {es:`Sería cómodo atribuirlo a la ignorancia, pero semejante explicación no resiste el menor análisis.`,
       note:`Sería 是条件式，表示「（那样做）会是……」，用于假设性评断。semejante 在此意为「这样的」，而非「相似的」。`},
      {es:`no por casualidad`,
       note:`固定短语，意为「并非偶然」。否定词前置时句子其他成分不变，但若出现在句首需注意重音。`},
      {es:`cuando esa autoridad se equivocó —como inevitablemente ocurre en toda empresa humana—, el coste en credibilidad fue muy superior al del error mismo.`,
       note:`破折号内是插入的评注从句。superior al… 是比较结构（superior a + 名词），al 是 a + el 的缩合。el del error mismo 中 el 代指 el coste。`},
      {es:`un hallazgo preliminar… circula por las redes despojado de esas cautelas y convertido en titular categórico`,
       note:`despojado 与 convertido 是过去分词作主语补足语（表示伴随状态），性数须与 hallazgo 一致（阳性单数）。`},
      {es:`su virtud no radica en no equivocarse, sino en corregirse.`,
       note:`radicar en 意为「在于」。no… sino… 结构中，sino 后接与前项平行的成分（此处为 en + 不定式）。`}
    ],
    questions:[
      {q:'¿Qué es lo novedoso de la desconfianza actual?', a:'Su generalización: ya no se duda de un especialista concreto, sino del conocimiento especializado como tal.'},
      {q:'¿Por qué no basta atribuirla a la ignorancia?', a:'Porque algunas corrientes escépticas surgen entre personas con formación universitaria.'},
      {q:'¿Qué error cometieron los propios expertos?', a:'Presentar su autoridad como incuestionable.'},
      {q:'¿Qué ocurre con un hallazgo preliminar en las redes?', a:'Circula despojado de sus cautelas y se convierte en titular categórico.'},
      {q:'¿En qué radica la virtud de la ciencia según el texto?', a:'No en no equivocarse, sino en corregirse.'}
    ]
  },
  {level:'C2', title:'论翻译的不可能之责', topic:'语言与文学', minutes:9,
    paragraphs:[
      {es:`Quien haya traducido un texto que amaba conoce una forma particular de duelo: la certeza de que aquello que se ha escrito no es, ni podrá ser nunca, aquello que se leyó. No se trata de impericia; se trata de una imposibilidad constitutiva.`,
       zh:`凡是翻译过自己所爱文本的人，都体会过一种特殊的哀悼：确信已写出的东西不是——也永远不可能成为——当初读到的那个东西。这不是技艺不精，而是一种构成性的不可能。`},
      {es:`La razón es que las lenguas no son sistemas intercambiables de etiquetas. Cada una ha ido sedimentando, a lo largo de siglos, asociaciones que ninguna otra comparte del todo: una palabra arrastra connotaciones, ecos literarios y silencios que no viajan.`,
       zh:`原因在于语言并非可以互换的标签系统。每一种语言都在数百年间逐渐沉积下其他语言无法完全共享的联想：一个词带着无法同行的内涵、文学回响与沉默。`},
      {es:`De ahí que la fidelidad, entendida como correspondencia término a término, sea una meta tan atractiva como ilusoria. El traductor que la persigue produce textos correctos y muertos: nada falta y nada respira.`,
       zh:`因此，把忠实理解为逐词对应，是一个既诱人又虚幻的目标。追求它的译者产出的是正确而死寂的文本：什么都不缺，也什么都不呼吸。`},
      {es:`Los mejores traductores que he conocido proceden de otro modo. Aceptan que han de perder algo y eligen deliberadamente qué perder, en función de aquello que el original consideraba irrenunciable. Es una decisión ética antes que estética.`,
       zh:`我认识的最优秀的译者做法不同。他们接受必然有所失，并依据原作视为不可放弃的东西，有意选择失去什么。这首先是一个伦理决定，其次才是美学决定。`},
      {es:`Esa elección, además, no se hace una vez y para siempre. Cambia con cada época, porque cambia lo que cada época considera irrenunciable. Las retraducciones no responden tanto a que las anteriores envejezcan cuanto a que nosotros ya no somos los mismos lectores.`,
       zh:`而且这一选择不是一劳永逸的。它随每个时代而变，因为每个时代视为不可放弃的东西在变。重译与其说是因为旧译变老，不如说是因为我们已不再是同样的读者。`},
      {es:`Se dirá que semejante modestia equivale a renunciar a la objetividad. Quizá. Pero conviene recordar que la alternativa —fingir que existe una equivalencia exacta y proceder como si se hubiera alcanzado— no es más rigurosa: es simplemente menos honesta.`,
       zh:`有人会说，这种谦逊等于放弃客观性。或许吧。但值得记住的是，另一种选择——假装存在完全的对等并当作已经实现——并不更严谨：它只是更不诚实。`},
      {es:`Traducir, en suma, no consiste en transportar un significado intacto de una lengua a otra, sino en tomar decisiones responsables sobre lo que se sacrifica. Quien no lo entiende así no traduce: transcribe.`,
       zh:`总而言之，翻译不在于把意义完好无损地从一种语言运到另一种语言，而在于对牺牲什么做出负责任的决定。不这样理解的人不是在翻译：是在誊抄。`}
    ],
    glossary:[
      {es:'el duelo', zh:'哀悼、丧失之痛'},
      {es:'la certeza', zh:'确信'},
      {es:'la impericia', zh:'技艺不精'},
      {es:'constitutivo', zh:'构成性的'},
      {es:'la etiqueta', zh:'标签'},
      {es:'sedimentar', zh:'沉积'},
      {es:'la connotación', zh:'内涵、言外之意'},
      {es:'el eco', zh:'回响'},
      {es:'la correspondencia', zh:'对应'},
      {es:'ilusorio', zh:'虚幻的'},
      {es:'irrenunciable', zh:'不可放弃的'},
      {es:'ético', zh:'伦理的'},
      {es:'la retraducción', zh:'重译'},
      {es:'la modestia', zh:'谦逊'},
      {es:'la equivalencia', zh:'对等'},
      {es:'riguroso', zh:'严谨的'},
      {es:'intacto', zh:'完好无损的'},
      {es:'transcribir', zh:'誊抄'}
    ],
    structures:[
      {es:`Quien haya traducido un texto que amaba conoce una forma particular de duelo.`,
       note:`quien haya traducido 是名词性关系从句作主语，用现在完成虚拟式表示「凡是曾经……的人」——虚拟式在此表达的是不确定的、泛指的集合，而非具体某人。`},
      {es:`aquello que se ha escrito no es, ni podrá ser nunca, aquello que se leyó`,
       note:`aquello que 意为「……的那个东西」。ni… nunca 构成否定加强。注意插入语 ni podrá ser nunca 被逗号隔开，插在主句谓语之间。`},
      {es:`Cada una ha ido sedimentando, a lo largo de siglos, asociaciones que ninguna otra comparte del todo.`,
       note:`ir + 副动词（ha ido sedimentando）表示逐渐、持续的过程。a lo largo de 意为「在……期间」。del todo 意为「完全」。`},
      {es:`De ahí que la fidelidad, entendida como correspondencia término a término, sea una meta tan atractiva como ilusoria.`,
       note:`de ahí que + 虚拟式（sea）。entendida como… 是过去分词短语作后置定语，修饰 la fidelidad。tan… como… 在此表示「既……又……」。`},
      {es:`Las retraducciones no responden tanto a que las anteriores envejezcan cuanto a que nosotros ya no somos los mismos lectores.`,
       note:`no tanto… cuanto… 意为「与其说……不如说……」。关键：a que 后面的动词语式不同——envejezcan 用虚拟式（因其为被否定的原因），somos 用陈述式（因其为被肯定的原因）。`},
      {es:`la alternativa —fingir que existe una equivalencia exacta y proceder como si se hubiera alcanzado— no es más rigurosa`,
       note:`como si 后必须用虚拟式过去时（hubiera alcanzado），表示与事实相反的假设。据此可知「已经达到」并非事实。`}
    ],
    questions:[
      {q:'¿Por qué el autor califica la imposibilidad de traducir como «constitutiva»?', a:'Porque las lenguas no son sistemas intercambiables de etiquetas: arrastran asociaciones que no viajan.'},
      {q:'¿Qué produce el traductor que persigue la fidelidad término a término?', a:'Textos correctos y muertos: nada falta y nada respira.'},
      {q:'¿Qué caracteriza a los mejores traductores según el autor?', a:'Aceptan que han de perder algo y eligen deliberadamente qué perder.'},
      {q:'¿Por qué se retraduce a los clásicos?', a:'Porque cambia lo que cada época considera irrenunciable: ya no somos los mismos lectores.'},
      {q:'¿Qué diferencia hay entre traducir y transcribir?', a:'Traducir es tomar decisiones responsables sobre lo que se sacrifica; transcribir es fingir que el significado se transporta intacto.'}
    ]
  },
  {level:'C2', title:'时间、记忆与自我', topic:'哲学与心理', minutes:9,
    paragraphs:[
      {es:`Decimos «yo» con una seguridad que el examen desmiente. Bajo esa palabra no hay una sustancia estable, sino un relato que se reescribe sin cesar y que, precisamente por reescribirse, se percibe como continuo.`,
       zh:`我们说出"我"时带着一种经不起审视的确定。这个词之下并没有稳固的实体，而是一个不断被改写的叙事，而正因为它被改写，才被感知为连续的。`},
      {es:`La paradoja merece detenerse. Si cada recuerdo se reconstruye cada vez que se evoca, y si esa reconstrucción incorpora el estado de ánimo del momento, entonces lo que llamamos pasado es en parte un producto del presente que lo recuerda.`,
       zh:`这个悖论值得停下来想一想。如果每一次回忆被唤起时都被重新构建，而这种重建又融入了当下的心境，那么我们所称的过去，有一部分是回忆它的当下所产出的。`},
      {es:`De ello no se sigue que la memoria sea pura invención —sería un absurdo—, sino algo más incómodo: que no disponemos de un criterio independiente para distinguir lo que recordamos de lo que hemos ido añadiendo al recordarlo.`,
       zh:`由此并不能推出记忆纯属虚构——那将是荒谬的——而是推出更令人不适的一点：我们并没有一个独立的标准来区分我们所记住的，与我们在回忆过程中不断添加进去的。`},
      {es:`Algunos filósofos han extraído de aquí una conclusión radical: que la identidad personal es una ficción útil, una convención que nos permite actuar sin tener que resolver un problema insoluble en cada momento.`,
       zh:`一些哲学家由此得出一个激进结论：人格同一性是一种有用的虚构，一种让我们无需每时每刻去解决一个无解难题就能行动的约定。`},
      {es:`Otros, en cambio, consideran que semejante tesis confunde el mapa con el territorio. Que el relato sea revisable no implica que no haya nada que se revise; la fragilidad del testimonio no demuestra la inexistencia del testigo.`,
       zh:`另一些人则认为，这一论断混淆了地图与疆域。叙事可以被修订，并不意味着没有东西在被修订；证词脆弱，并不能证明证词人不存在。`},
      {es:`Quizá el desacuerdo no sea resoluble, y quizá eso mismo sea lo interesante. Lo que ambas posiciones comparten es una exigencia de honestidad: renunciar a la ilusión de transparencia y aceptar que, al hablar de nosotros mismos, siempre hablamos también de algo que se nos escapa.`,
       zh:`或许这一分歧无法解决，而这本身或许才是有意思的地方。两种立场共同拥有的，是一种诚实的要求：放弃透明性的幻觉，接受这一点——当我们谈论自己时，我们总也在谈论某种逃离我们的东西。`}
    ],
    glossary:[
      {es:'la sustancia', zh:'实体'},
      {es:'el relato', zh:'叙事'},
      {es:'sin cesar', zh:'不停地'},
      {es:'la paradoja', zh:'悖论'},
      {es:'evocar', zh:'唤起（记忆）'},
      {es:'incorporar', zh:'纳入、融入'},
      {es:'el estado de ánimo', zh:'心境'},
      {es:'seguirse de', zh:'由此推出'},
      {es:'el criterio', zh:'标准'},
      {es:'extraer', zh:'得出、提取'},
      {es:'la identidad personal', zh:'人格同一性'},
      {es:'la convención', zh:'约定'},
      {es:'insoluble', zh:'无解的'},
      {es:'revisable', zh:'可修订的'},
      {es:'la fragilidad', zh:'脆弱性'},
      {es:'el testigo', zh:'证人'},
      {es:'la transparencia', zh:'透明'},
      {es:'escaparse', zh:'逃逸、无法把握'}
    ],
    structures:[
      {es:`un relato que se reescribe sin cesar y que, precisamente por reescribirse, se percibe como continuo`,
       note:`两个 que 并列引导定语从句修饰 un relato。por + 不定式（por reescribirse）表原因，此处前置于谓语，强调因果。`},
      {es:`Si cada recuerdo se reconstruye cada vez que se evoca, y si esa reconstrucción incorpora el estado de ánimo del momento, entonces…`,
       note:`两个 si 引导的条件从句并列。cada vez que 引导时间从句，用陈述式（se evoca），因为描述的是每次都会发生的事实。entonces 引出结论。`},
      {es:`De ello no se sigue que la memoria sea pura invención, sino algo más incómodo.`,
       note:`de ello se sigue que 意为「由此得出」。注意 no se sigue que 后接虚拟式（sea），因为否定了一个推论；而 sino 后接的肯定部分保持名词短语。`},
      {es:`la fragilidad del testimonio no demuestra la inexistencia del testigo`,
       note:`双重否定在此是修辞手法：no demuestra la inexistencia = 并不证明其不存在。注意 inexistencia 是通过前缀 in- 构成的名词。`},
      {es:`al hablar de nosotros mismos, siempre hablamos también de algo que se nos escapa`,
       note:`al + 不定式表示「在做……时」。nosotros mismos 加强语气。se nos escapa 中 se 是自复被动标记，nos 是与格，意为「从我们这里逃逸」。`}
    ],
    questions:[
      {q:'¿Qué se esconde bajo la palabra «yo» según el texto?', a:'No una sustancia estable, sino un relato que se reescribe sin cesar.'},
      {q:'¿Qué papel juega el estado de ánimo en el recuerdo?', a:'Se incorpora a la reconstrucción, de modo que el pasado es en parte producto del presente.'},
      {q:'¿Qué conclusión radical extraen algunos filósofos?', a:'Que la identidad personal es una ficción útil y una convención.'},
      {q:'¿Qué objeción se les opone?', a:'Que confunden el mapa con el territorio: la fragilidad del testimonio no prueba la inexistencia del testigo.'},
      {q:'¿Qué comparten ambas posiciones?', a:'Una exigencia de honestidad: renunciar a la ilusión de transparencia.'}
    ]
  },
  {level:'B2', title:'睡眠不足的社会成本', topic:'健康与社会', minutes:6,
    paragraphs:[
      {es:`Dormir mal se ha convertido en una seña de identidad casi respetable. Se presume de acostarse tarde, de madrugar y de rendir con cinco horas de sueño, como si el cansancio fuera una medalla.`,
       zh:`睡眠不足几乎成了一种值得自豪的身份标志。人们炫耀自己睡得晚、起得早、睡五小时还能干活，仿佛疲惫是一枚奖章。`},
      {es:`La evidencia científica, sin embargo, va en dirección contraria. La falta crónica de sueño deteriora la memoria, debilita las defensas y aumenta el riesgo cardiovascular; y lo hace de forma acumulativa, sin que el afectado lo perciba.`,
       zh:`然而科学证据指向相反方向。长期睡眠不足会损害记忆、削弱免疫力、增加心血管风险；而且它是累积发生的，当事人往往察觉不到。`},
      {es:`Lo llamativo es el sesgo con que juzgamos el fenómeno. Quien duerme ocho horas es tachado de poco ambicioso, mientras que quien se queda trabajando hasta la madrugada recibe elogios, aunque su rendimiento real sea inferior al de alguien descansado.`,
       zh:`值得注意的是我们评判这一现象时的偏见。睡八小时的人被说成没有上进心，而通宵工作到凌晨的人却获得赞扬——尽管他的实际产出还不如一个休息充足的人。`},
      {es:`El coste, además, no es solo individual. Los errores por somnolencia en hospitales, transportes y plantas industriales se cuentan por miles cada año, y muchos de ellos habrían sido evitables con turnos mejor diseñados.`,
       zh:`而且这一代价不仅是个人的。医院、交通和工业设施中因困倦造成的事故每年数以千计，其中许多只要把班次设计得更合理就可以避免。`},
      {es:`Cambiar esto exige algo más que consejos sobre higiene del sueño. Requiere revisar una cultura laboral que confunde la disponibilidad permanente con el compromiso, y que premia la presencia en lugar del resultado.`,
       zh:`要改变这一点，需要的远不止关于睡眠卫生的建议。它要求重新审视一种把"随时待命"混同于"敬业"、把出勤而非结果当作奖励标准的职场文化。`}
    ],
    glossary:[
      {es:'la seña de identidad', zh:'身份标志'},
      {es:'presumir de', zh:'炫耀、以……自豪'},
      {es:'madrugar', zh:'早起'},
      {es:'rendir', zh:'产出、发挥'},
      {es:'crónico', zh:'长期的、慢性的'},
      {es:'deteriorar', zh:'损害'},
      {es:'las defensas', zh:'免疫力'},
      {es:'acumulativo', zh:'累积的'},
      {es:'tachar de', zh:'指责为'},
      {es:'la somnolencia', zh:'困倦'},
      {es:'evitable', zh:'可避免的'},
      {es:'el turno', zh:'班次'},
      {es:'la higiene del sueño', zh:'睡眠卫生'}
    ],
    structures:[
      {es:`como si el cansancio fuera una medalla`,
       note:`como si 后必须用虚拟式过去时（fuera），表示与事实相反的比喻。`},
      {es:`lo hace de forma acumulativa, sin que el afectado lo perciba`,
       note:`sin que 后接虚拟式（perciba）。el afectado 是名词化的过去分词，意为「受影响者」。`},
      {es:`Quien duerme ocho horas es tachado de poco ambicioso`,
       note:`quien + 陈述式 表泛指（此处描述一般现象，非不确定对象）。tachar de ＝「指责为」。`},
      {es:`muchos de ellos habrían sido evitables con turnos mejor diseñados`,
       note:`habrían sido 是条件式完成时，表过去未实现的可能性；con + 名词短语表条件。`}
    ],
    questions:[
      {q:'¿Por qué el autor dice que dormir mal es «casi respetable»?', a:'Porque se presume de dormir poco, como si el cansancio fuera una medalla.'},
      {q:'¿Qué efectos tiene la falta crónica de sueño?', a:'Deteriora la memoria, debilita las defensas y aumenta el riesgo cardiovascular, de forma acumulativa.'},
      {q:'¿En qué consiste el sesgo al juzgar el fenómeno?', a:'Se tacha de poco ambicioso a quien duerme ocho horas y se elogia a quien trabaja hasta la madrugada.'},
      {q:'¿Qué cambio se requiere para resolverlo?', a:'Revisar una cultura laboral que premia la presencia en lugar del resultado.'}
    ]
  },
  {level:'B2', title:'为什么公益广告常常失效', topic:'传播与社会', minutes:6,
    paragraphs:[
      {es:`Las campañas de concienciación suelen partir de una premisa razonable: si la gente supiera lo grave que es un problema, actuaría en consecuencia. La experiencia indica lo contrario casi con monotonía.`,
       zh:`公益宣传往往始于一个合理的预设：如果人们知道某个问题有多严重，就会相应行动。经验却几乎一成不变地表明事实相反。`},
      {es:`El primer motivo es que el miedo paraliza antes que moviliza. Cuando el mensaje presenta una amenaza enorme y difusa —el cambio climático, por ejemplo—, el receptor concluye que su acción individual es irrelevante y no hace nada.`,
       zh:`第一个原因是恐惧先使人瘫痪，而不是促人行动。当信息呈现的是一个巨大而模糊的威胁时——比如气候变化——接收者会得出结论：自己的个人行动无关紧要，于是什么也不做。`},
      {es:`El segundo es la llamada «fatiga de compasión». La exposición continua a imágenes dramáticas agota la capacidad de respuesta emocional, de modo que el mensaje número cien produce menos efecto que el primero.`,
       zh:`第二个是所谓的"同情疲劳"。持续暴露于戏剧性的画面会耗尽情感回应能力，因此第一百条信息的效果反而不如第一条。`},
      {es:`El tercero, y quizá el más decisivo, es que se pide un cambio sin facilitarlo. Se exhorta a reciclar, pero los contenedores están lejos; se anima a usar el transporte público, pero el servicio es lento y caro.`,
       zh:`第三个、或许也是最关键的一个，是要求改变却没有为之提供便利。呼吁回收，但回收桶很远；鼓励乘坐公共交通，但服务又慢又贵。`},
      {es:`De ahí que las campañas más eficaces hayan dejado de apelar a la culpa y se centren en reducir la fricción: hacer que la conducta deseada sea la más fácil. La persuasión, en definitiva, rara vez gana a la conveniencia.`,
       zh:`因此最有效的宣传已不再诉诸愧疚，而是着眼于降低摩擦：让期望的行为成为最省事的选择。说到底，说服很难战胜便利。`}
    ],
    glossary:[
      {es:'la concienciación', zh:'意识提升、宣传'},
      {es:'la premisa', zh:'前提'},
      {es:'en consecuencia', zh:'相应地'},
      {es:'paralizar', zh:'使瘫痪'},
      {es:'difuso', zh:'模糊的'},
      {es:'la fatiga de compasión', zh:'同情疲劳'},
      {es:'agotar', zh:'耗尽'},
      {es:'exhortar a', zh:'劝告、呼吁'},
      {es:'el contenedor', zh:'垃圾回收桶'},
      {es:'la fricción', zh:'摩擦、阻力'},
      {es:'la conveniencia', zh:'便利'}
    ],
    structures:[
      {es:`si la gente supiera lo grave que es un problema, actuaría en consecuencia`,
       note:`非现实条件句：si + 虚拟式过去时（supiera）→ 条件式（actuaría）。lo grave que es ＝「它有多严重」。`},
      {es:`el miedo paraliza antes que moviliza`,
       note:`antes que 在此表「而不是、优先于」，前后动词保持平行。`},
      {es:`de modo que el mensaje número cien produce menos efecto que el primero`,
       note:`de modo que 表结果，用陈述式。menos… que… 比较结构。`},
      {es:`De ahí que las campañas más eficaces hayan dejado de apelar a la culpa`,
       note:`de ahí que + 虚拟式（hayan dejado）。dejar de + 不定式 ＝「不再」。`}
    ],
    questions:[
      {q:'¿Cuál es la premisa habitual de las campañas?', a:'Que si la gente supiera lo grave que es el problema, actuaría en consecuencia.'},
      {q:'¿Qué efecto tiene el miedo en los mensajes?', a:'Paraliza antes que moviliza.'},
      {q:'¿Qué es la «fatiga de compasión»?', a:'El agotamiento de la capacidad de respuesta emocional por exposición continua.'},
      {q:'¿En qué se centran las campañas más eficaces?', a:'En reducir la fricción, haciendo que la conducta deseada sea la más fácil.'}
    ]
  },
  {level:'B2', title:'城市里的孤独', topic:'城市与社会', minutes:6,
    paragraphs:[
      {es:`Vivir rodeado de gente y sentirse solo no son experiencias contradictorias. Las grandes ciudades concentran millones de personas y, al mismo tiempo, registran algunos de los índices de soledad más altos.`,
       zh:`身边人来人往却感到孤独，这两种体验并不矛盾。大城市聚集了数百万人，同时也记录下一些最高的孤独率。`},
      {es:`La explicación no está en la cantidad de contactos, sino en su naturaleza. Un saludo en el ascensor o una conversación breve en la caja del supermercado generan lo que los sociólogos llaman «vínculos débiles»: útiles, pero insuficientes para sostener a alguien en una crisis.`,
       zh:`原因不在于接触的数量，而在于其性质。电梯里的一声问候或超市收银台前的短暂交谈，产生的是社会学家所称的"弱联系"：有用，但不足以在危机中支撑一个人。`},
      {es:`A esto se añade la movilidad. Quien cambia de ciudad cada pocos años por trabajo reconstruye su red social una y otra vez, y cada reconstrucción cuesta tiempo y energía que no siempre están disponibles.`,
       zh:`此外还有流动性。因工作每隔几年就换城市的人，要一次次重建自己的社交网络，而每次重建都要付出时间和精力，而这些并不总是具备。`},
      {es:`El diseño urbano agrava o alivia el problema. Los barrios con espacios comunes —plazas, mercados, bibliotecas— favorecen los encuentros casuales; los desarrollos residenciales cerrados, en cambio, los reducen casi a cero.`,
       zh:`城市设计会加剧或缓解这一问题。拥有公共空间的街区——广场、市场、图书馆——有利于偶遇；而封闭式住宅区则几乎把偶遇降到零。`},
      {es:`De ahí que algunas administraciones hayan empezado a tratar la soledad como un asunto de salud pública y no como una cuestión privada. Los datos sobre mortalidad asociada a la soledad, comparables a los del tabaquismo, lo justifican.`,
       zh:`因此一些行政机构开始把孤独当作公共卫生问题，而不是私人问题来处理。与孤独相关的死亡率数据——可与吸烟相比——为这一做法提供了依据。`}
    ],
    glossary:[
      {es:'el índice', zh:'比率、指数'},
      {es:'contradictorio', zh:'矛盾的'},
      {es:'el vínculo débil', zh:'弱联系'},
      {es:'sostener', zh:'支撑'},
      {es:'la movilidad', zh:'流动性'},
      {es:'la red social', zh:'社交网络'},
      {es:'la reconstrucción', zh:'重建'},
      {es:'agravar', zh:'加剧'},
      {es:'aliviar', zh:'缓解'},
      {es:'el desarrollo residencial', zh:'住宅小区'},
      {es:'la administración', zh:'行政机构'},
      {es:'la mortalidad', zh:'死亡率'},
      {es:'el tabaquismo', zh:'吸烟（行为）'}
    ],
    structures:[
      {es:`lo que los sociólogos llaman «vínculos débiles»`,
       note:`lo que + 从句 ＝「……所称的东西」，作 generate 的宾语。注意 llamar 后直接接名词，不加 como。`},
      {es:`generan lo que los sociólogos llaman vínculos débiles: útiles, pero insuficientes`,
       note:`冒号后是补语，形容词短语作后置修饰，省略了 son。`},
      {es:`cada reconstrucción cuesta tiempo y energía que no siempre están disponibles`,
       note:`cuesta 在此意为「耗费」。关系从句用陈述式，因为描述的是事实性限制。`},
      {es:`De ahí que algunas administraciones hayan empezado a tratar la soledad como un asunto de salud pública`,
       note:`de ahí que + 虚拟式。tratar A como B ＝「把 A 当作 B 处理」。`}
    ],
    questions:[
      {q:'¿En qué se diferencia la soledad urbana de la falta de contactos?', a:'En la naturaleza de los contactos: los vínculos débiles son insuficientes para sostener a alguien en crisis.'},
      {q:'¿Qué papel juega la movilidad?', a:'Obliga a reconstruir la red social una y otra vez, con coste de tiempo y energía.'},
      {q:'¿Cómo influye el diseño urbano?', a:'Los espacios comunes favorecen los encuentros casuales; los desarrollos cerrados los reducen.'},
      {q:'¿Por qué se trata ahora como asunto de salud pública?', a:'Porque los datos de mortalidad asociada son comparables a los del tabaquismo.'}
    ]
  },
  {level:'B2', title:'语言学习中的高原期', topic:'学习与认知', minutes:6,
    paragraphs:[
      {es:`Casi todos los estudiantes de idiomas atraviesan una fase en la que dejan de notar progreso. Han pasado de entender frases a entender párrafos, pero llevan meses sintiéndose estancados.`,
       zh:`几乎所有语言学习者都会经历一个阶段：察觉不到进步。他们从能听懂句子进步到能听懂段落，却已经好几个月感到停滞。`},
      {es:`Este fenómeno, llamado «meseta», no indica falta de esfuerzo. Suele ocurrir precisamente porque las mejoras se han vuelto más pequeñas y más difíciles de percibir, mientras que el esfuerzo sigue siendo el mismo.`,
       zh:`这一现象被称为"高原期"，它并不表示努力不够。它往往恰恰是因为进步变得更小、更难察觉，而努力程度却不变。`},
      {es:`Hay una razón estructural. Las primeras semanas producen saltos visibles porque se aprenden las palabras más frecuentes, que aparecen constantemente. Después se pasa a un vocabulario más especializado que rara vez se encuentra en un texto cualquiera.`,
       zh:`这里有一个结构性原因。最初几周会有明显的跨越，因为学的是最高频的词，它们不断出现。之后进入的是更专门的词汇，在随便一篇文章里很少遇到。`},
      {es:`A esto se suma que el error cambia de naturaleza. Al principio los fallos eran de gramática básica y se corregían solos; ahora son de matiz, de registro o de colocación, y requieren que alguien los señale.`,
       zh:`此外，错误的性质也变了。起初错误是基础语法，会自动纠正；现在是细微差别、语域或搭配上的问题，需要有人指出来。`},
      {es:`Quienes superan la meseta suelen hacer dos cosas: cambian el tipo de práctica en lugar de aumentar la cantidad, y se someten a evaluación externa aunque resulte incómoda. Insistir con el mismo método rara vez sale de la meseta.`,
       zh:`走出高原期的人通常做两件事：改变练习类型而不是增加练习量，并接受外部评估——尽管这令人不适。用同一套方法死磕，很少能走出高原期。`}
    ],
    glossary:[
      {es:'atravesar', zh:'经历、穿过'},
      {es:'la fase', zh:'阶段'},
      {es:'el progreso', zh:'进步'},
      {es:'estancado', zh:'停滞的'},
      {es:'la meseta', zh:'高原期（学习停滞）'},
      {es:'la mejora', zh:'改进'},
      {es:'percibir', zh:'察觉'},
      {es:'estructural', zh:'结构性的'},
      {es:'el salto', zh:'跨越'},
      {es:'especializado', zh:'专门的'},
      {es:'el matiz', zh:'细微差别'},
      {es:'el registro', zh:'语域'},
      {es:'la colocación', zh:'搭配'},
      {es:'la evaluación externa', zh:'外部评估'}
    ],
    structures:[
      {es:`Casi todos los estudiantes atraviesan una fase en la que dejan de notar progreso`,
       note:`en la que 引导关系从句修饰 fase。dejar de + 不定式 ＝「停止做」。`},
      {es:`Suele ocurrir precisamente porque las mejoras se han vuelto más pequeñas`,
       note:`soler + 不定式 表惯常。volverse + 形容词 表状态变化。porque 引导原因从句，用陈述式（事实原因）。`},
      {es:`requieren que alguien los señale`,
       note:`requerir que + 虚拟式（señale）。los 回指 los fallos。`},
      {es:`Quienes superan la meseta suelen hacer dos cosas`,
       note:`quienes ＝「那些……的人」，复数名词性关系从句作主语，谓语用复数 suelen。`},
      {es:`aunque resulte incómoda`,
       note:`aunque + 虚拟式（resulte），因说话人将其视为可能但未必成立的情况。`}
    ],
    questions:[
      {q:'¿Qué es la «meseta» en el aprendizaje de idiomas?', a:'Una fase en la que se deja de notar progreso.'},
      {q:'¿Por qué se produce, según el texto?', a:'Porque las mejoras se vuelven más pequeñas y difíciles de percibir, sin que cambie el esfuerzo.'},
      {q:'¿Cómo cambia la naturaleza del error?', a:'Pasa de gramática básica a matiz, registro o colocación, y requiere que alguien lo señale.'},
      {q:'¿Qué hacen quienes superan la meseta?', a:'Cambian el tipo de práctica y se someten a evaluación externa.'}
    ]
  },
  {level:'C1', title:'论公共空间的消失', topic:'城市与公民', minutes:8,
    paragraphs:[
      {es:`Toda sociedad necesita lugares donde no sea obligatorio consumir para permanecer. Son esos espacios, y no los discursos, los que hacen posible la convivencia entre desconocidos.`,
       zh:`任何社会都需要一些地方，在那里停留不必以消费为前提。正是这些空间——而非说教——使陌生人之间的共处成为可能。`},
      {es:`La ciudad contemporánea tiende a suprimir esos lugares sin declararlo. No los prohíbe: los sustituye por espacios que parecen públicos pero están diseñados para excluir a quien no compra, no consume o simplemente no encaja.`,
       zh:`当代城市倾向于在不加宣告的情况下取消这类场所。它并不是禁止它们，而是用看似公共、实则设计来排除不消费、不购物或单纯"不合时宜"之人的空间来取代它们。`},
      {es:`El banco de plaza con reposabrazos individuales es un ejemplo elocuente: impide tumbarse, es decir, impide permanecer. No hace falta ningún cartel para comunicar quién es bienvenido.`,
       zh:`公园里那种带独立扶手的长椅是个很有说服力的例子：它让人无法躺下，也就是无法停留。无需任何标牌就能传达出谁才是受欢迎的人。`},
      {es:`Hay quien sostiene que se trata de una simple cuestión de seguridad y orden. La objeción merece consideración, pero conviene advertir que el orden así entendido excluye siempre a los mismos: a quienes no tienen dónde ir.`,
       zh:`有人主张这只是一个安全与秩序问题。这一反驳值得考虑，但应当指出：如此理解的秩序，被排除的总是同一批人——那些无处可去的人。`},
      {es:`Frente a esto, algunas ciudades han ensayado lo contrario: bibliotecas de acceso libre, plazas sin mobiliario disuasorio, mercados que siguen siendo mercados y no parques temáticos. Los resultados, medidos en cohesión social, son difíciles de cuantificar pero difíciles de negar.`,
       zh:`对此，一些城市尝试了相反路径：自由进入的图书馆、没有"劝退式"设施的广场、仍是市场而非主题公园的市场。以社会凝聚力衡量的结果难以量化，却难以否认。`},
      {es:`La cuestión de fondo no es estética sino política: decidir si la ciudad pertenece a quienes la habitan o solo a quienes la consumen. Esa decisión rara vez se toma de forma explícita, y precisamente por eso conviene hacerla visible.`,
       zh:`根本问题不是美学问题，而是政治问题：决定这座城市属于居住它的人，还是只属于消费它的人。这个决定很少被明示；正因如此，才应当让它变得可见。`}
    ],
    glossary:[
      {es:'la convivencia', zh:'共处'},
      {es:'suprimir', zh:'取消、消除'},
      {es:'sustituir por', zh:'以……取代'},
      {es:'excluir', zh:'排斥'},
      {es:'el reposabrazos', zh:'扶手'},
      {es:'elocuente', zh:'有说服力的'},
      {es:'tumbarse', zh:'躺下'},
      {es:'la objeción', zh:'反驳'},
      {es:'disuasorio', zh:'劝退式的'},
      {es:'la cohesión social', zh:'社会凝聚力'},
      {es:'cuantificar', zh:'量化'},
      {es:'la cuestión de fondo', zh:'根本问题'},
      {es:'explícito', zh:'明示的'}
    ],
    structures:[
      {es:`Son esos espacios, y no los discursos, los que hacen posible la convivencia.`,
       note:`es… los que… 强调句式，强调主语。y no los discursos 是对比插入成分。`},
      {es:`están diseñados para excluir a quien no compra`,
       note:`a quien ＝「对那个……的人」。quien 单数，指任一此类个体，谓语用单数。`},
      {es:`Hay quien sostiene que se trata de una simple cuestión de seguridad.`,
       note:`hay quien + 陈述式（sostiene）＝「有人主张」；若用 hay quienes 则谓语用复数。`},
      {es:`conviene advertir que el orden así entendido excluye siempre a los mismos`,
       note:`conviene + 不定式。así entendido 是过去分词短语作后置修饰，等同于 entendido de este modo。`},
      {es:`decidir si la ciudad pertenece a quienes la habitan o solo a quienes la consumen`,
       note:`si 引导间接疑问。a quienes + 陈述式（habitan / consumen），因指具体的一类人。`}
    ],
    questions:[
      {q:'¿Qué define el autor como espacio público necesario?', a:'Aquel donde no es obligatorio consumir para permanecer.'},
      {q:'¿Cómo se suprimen esos lugares según el texto?', a:'No prohibiéndolos, sino sustituyéndolos por espacios diseñados para excluir.'},
      {q:'¿Qué ejemplo se aporta?', a:'El banco con reposabrazos individuales, que impide permanecer.'},
      {q:'¿Qué objeción se menciona y cómo se responde?', a:'Que es una cuestión de seguridad y orden; se responde que ese orden excluye siempre a los mismos.'},
      {q:'¿Cuál es la cuestión de fondo?', a:'Decidir si la ciudad pertenece a quienes la habitan o solo a quienes la consumen.'}
    ]
  },
  {level:'C1', title:'专家与民主：技术决策的难题', topic:'政治与治理', minutes:8,
    paragraphs:[
      {es:`Muchas decisiones contemporáneas —la política energética, la regulación de algoritmos, la gestión de pandemias— exigen conocimientos que la ciudadanía no posee y que ningún ciudadano puede adquirir a tiempo.`,
       zh:`许多当代决策——能源政策、算法监管、疫情管理——所需的知识是公众不具备、也没有任何公民能及时掌握的。`},
      {es:`De ahí surgen dos tentaciones simétricas. La primera es dejar decidir a los técnicos, con el argumento de que la complejidad desaconseja el debate público. La segunda es negar toda autoridad experta y tratar cualquier dictamen como una opinión entre otras.`,
       zh:`由此产生两种对称的诱惑。第一种是把决定权交给技术专家，理由是复杂性不宜公开辩论。第二种是否认一切专家权威，把任何专业意见都当作众多意见之一。`},
      {es:`Ambas comparten un mismo error: confundir el plano de los hechos con el plano de los valores. Un experto puede decirnos qué consecuencias tendrá una medida; no puede decirnos, en cuanto experto, si esas consecuencias son aceptables.`,
       zh:`两者犯同一个错误：混淆事实层面与价值层面。专家可以告诉我们某项措施会产生什么后果；但作为专家，他无法告诉我们那些后果是否可以接受。`},
      {es:`La distinción tiene consecuencias prácticas. Si se pide a los expertos que decidan el fin, se les otorga un poder que no les corresponde y, además, se les hace responsables de un desacuerdo que es político, no técnico.`,
       zh:`这一区分有实际后果。如果要求专家决定目的，就赋予了他们本不属于他们的权力，而且让他们承担一种本质上是政治而非技术的分歧。`},
      {es:`Si se niega todo peso al conocimiento experto, se decide a ciegas y suelen pagarlo los más vulnerables, que son quienes menos pueden adaptarse a un error colectivo.`,
       zh:`如果否认专家知识的一切分量，就会在盲目中做决定，而付出代价的往往是最脆弱的人——他们最无力应对集体性的错误。`},
      {es:`Lo razonable, aunque poco espectacular, es articular ambos planos: que los expertos delimiten el abanico de opciones y sus costes, y que la decisión sobre cuál elegir corresponda a un procedimiento político transparente y revocable.`,
       zh:`合理的做法虽不耀眼，却是把两个层面衔接起来：由专家界定可选方案的范围及其代价，而选择哪一个的决定，交由透明且可撤销的政治程序。`}
    ],
    glossary:[
      {es:'la ciudadanía', zh:'公民（总称）'},
      {es:'simétrico', zh:'对称的'},
      {es:'la tentación', zh:'诱惑'},
      {es:'desaconsejar', zh:'不主张、劝止'},
      {es:'el dictamen', zh:'专业意见'},
      {es:'la autoridad experta', zh:'专家权威'},
      {es:'el plano', zh:'层面'},
      {es:'otorgar', zh:'授予'},
      {es:'corresponder a', zh:'属于、应由'},
      {es:'el desacuerdo', zh:'分歧'},
      {es:'a ciegas', zh:'盲目地'},
      {es:'vulnerable', zh:'脆弱的'},
      {es:'articular', zh:'衔接、协调'},
      {es:'el abanico de opciones', zh:'可选方案范围'},
      {es:'revocable', zh:'可撤销的'}
    ],
    structures:[
      {es:`exigen conocimientos que la ciudadanía no posee y que ningún ciudadano puede adquirir a tiempo`,
       note:`两个 que 并列引导定语从句；第二个从句用陈述式，因表示客观事实限制。`},
      {es:`De ahí surgen dos tentaciones simétricas.`,
       note:`de ahí surgir ＝「由此产生」。注意是 surgen（复数），主语为 dos tentaciones。`},
      {es:`no puede decirnos, en cuanto experto, si esas consecuencias son aceptables`,
       note:`en cuanto experto ＝「作为专家」。en cuanto + 名词 表身份，与 en cuanto（一……就）不同，需据语境区分。`},
      {es:`los más vulnerables, que son quienes menos pueden adaptarse`,
       note:`que 引导非限定性定语从句；quienes menos pueden ＝「最无法……的那些人」。`},
      {es:`que la decisión sobre cuál elegir corresponda a un procedimiento político`,
       note:`corresponder a ＝「属于、归……负责」。que 引出的从句用虚拟式（corresponda），因整个结构表达建议性分配。`}
    ],
    questions:[
      {q:'¿Qué caracteriza a las decisiones contemporáneas según el texto?', a:'Exigen conocimientos que la ciudadanía no posee ni puede adquirir a tiempo.'},
      {q:'¿Cuáles son las dos tentaciones simétricas?', a:'Dejar decidir solo a los técnicos, o negar toda autoridad experta.'},
      {q:'¿Cuál es el error común a ambas?', a:'Confundir el plano de los hechos con el plano de los valores.'},
      {q:'¿Qué consecuencia tiene negar el conocimiento experto?', a:'Se decide a ciegas y lo pagan los más vulnerables.'},
      {q:'¿Qué propone el autor?', a:'Que los expertos delimiten las opciones y sus costes, y que la decisión corresponda a un procedimiento político transparente y revocable.'}
    ]
  },
  {level:'C1', title:'论闲散的消失', topic:'文化与生活', minutes:8,
    paragraphs:[
      {es:`Hubo un tiempo en que la palabra «ocio» designaba un estado del espíritu y no un sector económico. Hoy el ocio se ha vuelto una tarea más: hay que aprovecharlo, optimizarlo y, si es posible, producir algo con él.`,
       zh:`曾有一段时间，"闲暇"一词指的是精神状态，而不是一个经济部门。如今闲暇已变成又一项任务：必须利用它、优化它，如果可能，还要用它产出些什么。`},
      {es:`La consecuencia es que hemos perdido la capacidad de estar sin hacer nada sin sentir culpa. El aburrimiento, que durante siglos fue el precio de la vida contemplativa, se ha convertido en un defecto que conviene corregir.`,
       zh:`其后果是我们丧失了无所事事而不感愧疚的能力。无聊在数百年间曾是沉思生活的代价，如今却成了一种应当纠正的缺陷。`},
      {es:`Cabe preguntarse qué se pierde con ello. La respuesta, según quienes han estudiado el fenómeno, es más de lo que parece: el aburrimiento es la condición en que surge buena parte de la creación y también el momento en que uno se encuentra con sus propios problemas.`,
       zh:`可以问：这样失去了什么。研究这一现象的人给出的答案是：比看上去的要多——无聊是大部分创造得以出现的条件，也是一个人与自身问题相遇的时刻。`},
      {es:`A ello se opone una objeción previsible: quien tiene poco tiempo libre no puede permitirse el lujo de desperdiciarlo. Es cierto, y sin embargo la objeción confunde la cantidad con la disposición: cinco minutos sin pantalla no son un lujo, sino una práctica.`,
       zh:`对此有一个可以预见的反驳：空闲时间少的人没有浪费它的余裕。这话没错，然而这个反驳把数量与安排混为一谈：五分钟不看屏幕不是奢侈，而是一种练习。`},
      {es:`El problema, en el fondo, no es la falta de tiempo, sino la incapacidad de tolerar un intervalo vacío. Y esa incapacidad no la impone el trabajo: la cultivamos nosotros, con la complicidad de un entorno diseñado para no dejarnos nunca solos con nosotros mismos.`,
       zh:`归根结底，问题不是缺少时间，而是无法忍受一段空白。而这种无能并非工作强加给我们的：是我们自己在培养它，而一个旨在让我们永不与自身独处的环境充当了同谋。`}
    ],
    glossary:[
      {es:'el ocio', zh:'闲暇'},
      {es:'designar', zh:'指称'},
      {es:'aprovechar', zh:'利用'},
      {es:'la culpa', zh:'愧疚'},
      {es:'el aburrimiento', zh:'无聊'},
      {es:'contemplativo', zh:'沉思的'},
      {es:'el defecto', zh:'缺陷'},
      {es:'la creación', zh:'创造'},
      {es:'previsible', zh:'可以预见的'},
      {es:'permitirse el lujo', zh:'有……的余裕'},
      {es:'la disposición', zh:'安排、状态'},
      {es:'tolerar', zh:'忍受'},
      {es:'la complicidad', zh:'同谋、共谋'},
      {es:'el entorno', zh:'环境'}
    ],
    structures:[
      {es:`Hubo un tiempo en que la palabra «ocio» designaba un estado del espíritu.`,
       note:`hubo un tiempo en que ＝「曾有一段时间」，从句用未完成过去时表当时的状态。`},
      {es:`El aburrimiento, que durante siglos fue el precio de la vida contemplativa, se ha convertido en un defecto.`,
       note:`非限定性定语从句用逗号隔开，起补充说明作用，不限定先行词。`},
      {es:`Cabe preguntarse qué se pierde con ello.`,
       note:`caber + 不定式 ＝「可以、有理由」。preguntarse 后接间接疑问句。`},
      {es:`la objeción confunde la cantidad con la disposición`,
       note:`confundir A con B ＝「把 A 与 B 混淆」。`},
      {es:`esa incapacidad no la impone el trabajo: la cultivamos nosotros`,
       note:`两个 la 均为直接宾语代词，前指 la incapacidad；后置是为了强调「不是工作强加的」。`}
    ],
    questions:[
      {q:'¿Qué cambio de significado ha sufrido la palabra «ocio»?', a:'Antes designaba un estado del espíritu; hoy es una tarea que hay que aprovechar.'},
      {q:'¿Qué se ha convertido el aburrimiento?', a:'En un defecto que conviene corregir.'},
      {q:'¿Qué se pierde, según los estudiosos?', a:'La condición en que surge buena parte de la creación y el encuentro con los propios problemas.'},
      {q:'¿Cómo responde el autor a la objeción de la falta de tiempo?', a:'Confunde cantidad con disposición: cinco minutos sin pantalla no son un lujo, sino una práctica.'},
      {q:'¿A quién atribuye la responsabilidad el autor?', a:'A nosotros mismos, con la complicidad de un entorno diseñado para no dejarnos solos.'}
    ]
  },
  {level:'C2', title:'论历史的用途与滥用', topic:'历史与思想', minutes:9,
    paragraphs:[
      {es:`Se nos enseña que conocer el pasado evita repetir sus errores. La fórmula es tranquilizadora y, tomada al pie de la letra, falsa: los errores se repiten con puntualidad escrupulosa, y quienes los cometen suelen tener un conocimiento detallado de sus antecedentes.`,
       zh:`我们被教导说，了解过去可以避免重蹈覆辙。这个说法令人安心，而若照字面理解，则是错误的：错误被一丝不苟地重复，而犯下这些错误的人，往往对前例有详尽的了解。`},
      {es:`Nietzsche ya advirtió que el exceso de memoria histórica paraliza. Quien se sabe heredero de veinte fracasos previos no actúa con más prudencia: actúa con más miedo, o compensa el miedo con temeridad, que es la forma más común de disfrazarlo.`,
       zh:`尼采早已提醒，过量的历史记忆会使人瘫痪。知道自己继承着二十次先前失败的人，行动时并不会更审慎：他行动时更恐惧，或者用鲁莽来补偿恐惧——而这是掩饰恐惧最常见的方式。`},
      {es:`De ahí que la historia sirva mejor para formular preguntas que para dictar respuestas. Enseña, si se la interroga bien, qué condiciones hicieron posible ciertas decisiones; no enseña qué debe hacerse cuando las condiciones son otras.`,
       zh:`因此，历史更适合用来提出问题，而不是给出答案。如果问得得当，它会告诉我们哪些条件使某些决定成为可能；它不会告诉我们，当条件不同时应当怎么做。`},
      {es:`Hay un segundo abuso, opuesto al primero, y quizá más frecuente hoy: el uso de la historia como arsenal. Se seleccionan los episodios que confirman la posición propia y se silencian los demás, con lo que el pasado deja de ser un objeto de estudio y pasa a ser un instrumento de legitimación.`,
       zh:`还有第二种滥用，与第一种相反，或许在今天更为常见：把历史当作弹药库。人们挑选那些能印证自身立场的片段，对其余部分保持沉默，于是过去不再是研究对象，而成为正当化的工具。`},
      {es:`Ambos abusos comparten un rasgo: tratan el pasado como algo que debe rendir un servicio al presente. Frente a ellos, la única actitud defendible es más modesta y más exigente a la vez: aceptar que el pasado fue real, que no estaba escrito para nosotros, y que comprenderlo puede obligarnos a cambiar de opinión.`,
       zh:`两种滥用有一个共同特点：都把过去当作应为当下效劳的东西。面对它们，唯一站得住脚的态度既更谦逊也更严格：接受过去曾是真实的，它不是为我们而写的，而理解它可能迫使我们改变看法。`},
      {es:`Quien estudia historia para confirmarse no estudia historia: busca un espejo. Y un espejo, por muy bien documentado que esté, nunca corrige a quien se mira en él.`,
       zh:`为确认自己而研究历史的人，并不是在研究历史：他在寻找一面镜子。而一面镜子，无论其依据多么详实，从不会纠正照镜的人。`}
    ],
    glossary:[
      {es:'tomar al pie de la letra', zh:'照字面理解'},
      {es:'escrupuloso', zh:'一丝不苟的'},
      {es:'el antecedente', zh:'前例'},
      {es:'advertir', zh:'提醒、警告'},
      {es:'el heredero', zh:'继承者'},
      {es:'la temeridad', zh:'鲁莽'},
      {es:'disfrazar', zh:'掩饰'},
      {es:'dictar', zh:'指定、口述'},
      {es:'interrogar', zh:'质问、探究'},
      {es:'el arsenal', zh:'弹药库'},
      {es:'silenciar', zh:'对……保持沉默'},
      {es:'la legitimación', zh:'正当化'},
      {es:'rendir un servicio', zh:'效劳'},
      {es:'exigente', zh:'要求高的'},
      {es:'el espejo', zh:'镜子'}
    ],
    structures:[
      {es:`La fórmula es tranquilizadora y, tomada al pie de la letra, falsa.`,
       note:`tomada al pie de la letra 是过去分词短语作插入语，修饰 la fórmula，性数一致（阴性单数）。`},
      {es:`Quien se sabe heredero de veinte fracasos previos no actúa con más prudencia.`,
       note:`quien + 陈述式 表泛指。saberse + 名词 ＝「自知是……」。`},
      {es:`Enseña, si se la interroga bien, qué condiciones hicieron posible ciertas decisiones.`,
       note:`se la interroga 是被动 se 结构，la 回指 la historia。si 引导条件，用陈述式（真实条件的泛化）。`},
      {es:`con lo que el pasado deja de ser un objeto de estudio`,
       note:`con lo que ＝「由此、于是」，引出结果。dejar de ser ＝「不再是」。`},
      {es:`por muy bien documentado que esté`,
       note:`por + 副词 + que + 虚拟式 ＝「无论多么……」。documentado 与主语 un espejo 保持阳性单数一致。`}
    ],
    questions:[
      {q:'¿Por qué es falsa, literalmente, la fórmula «conocer el pasado evita repetir errores»?', a:'Porque los errores se repiten y quienes los cometen suelen conocer bien sus antecedentes.'},
      {q:'¿Qué advirtió Nietzsche sobre el exceso de memoria histórica?', a:'Que paraliza; quien se sabe heredero de fracasos actúa con más miedo o con temeridad.'},
      {q:'¿Para qué sirve mejor la historia según el autor?', a:'Para formular preguntas, no para dictar respuestas.'},
      {q:'¿En qué consiste el segundo abuso?', a:'En usar la historia como arsenal: seleccionar lo que confirma la propia posición y silenciar el resto.'},
      {q:'¿Cuál es la actitud que el autor considera defendible?', a:'Aceptar que el pasado fue real, que no estaba escrito para nosotros, y que comprenderlo puede obligarnos a cambiar de opinión.'}
    ]
  },
  {level:'C2', title:'隐喻如何塑造政治', topic:'语言与政治', minutes:9,
    paragraphs:[
      {es:`Ningún debate político se libra sin metáforas, y pocas se examinan. Decimos que un país «está enfermo» y de ahí se sigue con naturalidad que necesita un diagnóstico, un tratamiento y, sobre todo, alguien que lo administre.`,
       zh:`没有一场政治辩论是不带隐喻进行的，而很少有隐喻被审视。我们说一个国家"病了"，由此自然而然地推出：它需要诊断、治疗，尤其是需要有人来施行。`},
      {es:`La metáfora no es un adorno del razonamiento: es una premisa disfrazada. Al aceptar la figura, el oyente acepta también el conjunto de consecuencias que la figura trae consigo, sin haberlas discutido una por una.`,
       zh:`隐喻不是推理的装饰：它是伪装成修辞的前提。一旦接受这个比喻，听者也就接受了这比喻所附带的一整套推论，而并未逐条讨论过它们。`},
      {es:`De ahí que las metáforas más eficaces sean las que ocultan mejor su carácter metafórico. «Crisis migratoria», «ola de delincuencia», «invasión»: cada una organiza los hechos de una manera determinada y hace difícil pensar en otra.`,
       zh:`因此最有效的隐喻是那些最能掩盖自身隐喻性质的隐喻。"移民危机""犯罪浪潮""入侵"：每一个都以特定方式组织事实，并使人们难以另作他想。`},
      {es:`Cabe objetar que el fenómeno es inevitable y que señalar las metáforas es una tarea pedante. Lo segundo sería cierto si el examen se detuviera en la figura; pero lo que importa no es la figura, sino qué decisiones vuelve impensables.`,
       zh:`可以反驳说这种现象不可避免，指出隐喻是件卖弄的事。如果审视止于修辞，那么后一点或许成立；但重要的不是修辞，而是它使哪些决定变得不可设想。`},
      {es:`Llamar «invasión» a un desplazamiento migratorio hace impensable la pregunta por sus causas, porque una invasión no tiene causas: tiene responsables. Y llamar «enfermo» a un país hace impensable preguntar si el problema está en su organización y no en su salud.`,
       zh:`把人口迁徙称为"入侵"，会让追问其成因变得不可设想，因为入侵没有成因：只有责任方。把一个国家称为"生病"，会让追问问题是否出在其组织结构而非其健康上变得不可设想。`},
      {es:`Examinar las metáforas no es un ejercicio de corrección lingüística. Es la única forma de recuperar preguntas que la propia manera de nombrar el problema había clausurado.`,
       zh:`审视隐喻不是语言纯正性的练习。它是唯一能重新找回那些被"命名问题的方式"本身封闭掉的提问的途径。`}
    ],
    glossary:[
      {es:'la metáfora', zh:'隐喻'},
      {es:'examinar', zh:'审视'},
      {es:'el diagnóstico', zh:'诊断'},
      {es:'administrar', zh:'施行、给药'},
      {es:'el adorno', zh:'装饰'},
      {es:'la premisa disfrazada', zh:'伪装的前提'},
      {es:'la figura', zh:'修辞、比喻'},
      {es:'el conjunto', zh:'整体、一整套'},
      {es:'ocultar', zh:'隐藏'},
      {es:'la ola', zh:'浪潮'},
      {es:'la delincuencia', zh:'犯罪'},
      {es:'pedante', zh:'卖弄的'},
      {es:'impensable', zh:'不可设想的'},
      {es:'el desplazamiento', zh:'迁徙'},
      {es:'clausurar', zh:'封闭、终止'}
    ],
    structures:[
      {es:`Ningún debate político se libra sin metáforas, y pocas se examinan.`,
       note:`ningún… sin… 双重否定表强调。pocas 前指 metáforas，省略了 las metáforas。`},
      {es:`de ahí se sigue con naturalidad que necesita un diagnóstico`,
       note:`de ahí se sigue que ＝「由此推出」。此处从句用陈述式（necesita），因推论被当作事实陈述。`},
      {es:`De ahí que las metáforas más eficaces sean las que ocultan mejor su carácter metafórico.`,
       note:`de ahí que + 虚拟式（sean）。las que ＝「那些……的（隐喻）」。`},
      {es:`Lo segundo sería cierto si el examen se detuviera en la figura.`,
       note:`条件式 + si + 虚拟式过去时，构成非现实条件句。detenerse en ＝「止于」。`},
      {es:`hace impensable la pregunta por sus causas`,
       note:`hacer + 形容词 + 名词 ＝「使……变得……」。la pregunta por ＝「关于……的提问」。`},
      {es:`preguntas que la propia manera de nombrar el problema había clausurado`,
       note:`过去完成时表示先于主句动作；la propia manera de nombrar ＝「命名方式本身」。`}
    ],
    questions:[
      {q:'¿Por qué se dice que la metáfora es «una premisa disfrazada»?', a:'Porque al aceptar la figura se aceptan sus consecuencias sin haberlas discutido.'},
      {q:'¿Qué caracteriza a las metáforas más eficaces?', a:'Que ocultan mejor su carácter metafórico.'},
      {q:'¿Qué objeción se plantea y cómo se responde?', a:'Que señalar metáforas es pedante; se responde que lo importante no es la figura, sino qué decisiones vuelve impensables.'},
      {q:'¿Por qué «invasión» impide preguntar por las causas?', a:'Porque una invasión no tiene causas, tiene responsables.'},
      {q:'¿Para qué sirve examinar las metáforas según el autor?', a:'Para recuperar preguntas que la manera de nombrar el problema había clausurado.'}
    ]
  },
  {level:'C2', title:'论品味的不可争辩与必须争辩', topic:'美学与批评', minutes:9,
    paragraphs:[
      {es:`«Sobre gustos no hay nada escrito» es un lugar común que sirve para cerrar discusiones y, de paso, para no examinar ninguno de los criterios que efectivamente empleamos al juzgar.`,
       zh:`"品味无可争辩"是一句用来终止讨论的套话，顺带也让人不必去审视我们评判时实际使用的任何标准。`},
      {es:`La fórmula es empíricamente falsa. Discutimos sobre gustos continuamente, y no lo hacemos al azar: apelamos a la coherencia de una obra, a su dificultad superada, a su capacidad de seguir diciendo algo después de muchas lecturas.`,
       zh:`这句话在经验上是假的。我们不断争论品味，而且并非随意而为：我们诉诸一部作品的内在一致性、它被克服的难度，以及它在多次阅读后仍能有所言说的能力。`},
      {es:`Lo que ocurre es que esos criterios rara vez se explicitan, en parte porque muchas veces los descubrimos al formularlos. Discutir sobre arte es, con frecuencia, el proceso por el cual averiguamos qué valoramos.`,
       zh:`问题在于这些标准很少被明说，部分原因是它们往往在我们表述它们的过程中才被发现。讨论艺术，常常正是我们弄清自己看重什么的过程。`},
      {es:`De ahí que la crítica tenga mala reputación: se la confunde con el veredicto. Un crítico que se limita a dictaminar —esto es bueno, esto es malo— no aporta nada; el que explica por qué algo funciona o fracasa nos da algo reutilizable, incluso cuando no coincidimos.`,
       zh:`因此批评的名声不好：它被混同于裁决。仅限于下判词的批评家——这个好、那个坏——毫无贡献；而解释某物为何奏效或失败的人，则给了我们可以复用的东西，即便我们并不认同。`},
      {es:`Cabe entonces reformular el lugar común: sobre gustos sí hay algo escrito, pero casi nunca se escribe de antemano. Se escribe en el acto mismo de argumentar, y quien se niega a argumentar no defiende su gusto: lo clausura.`,
       zh:`于是可以改写那句套话：关于品味确实有东西可写，但几乎从不预先写好。它是在论证的过程中写下的，而拒绝论证的人并不是在捍卫自己的品味：他是在封闭它。`},
      {es:`Nada de esto obliga a coincidir. La crítica no tiene por tarea producir unanimidad, sino hacer que el desacuerdo sea productivo: que al discrepar hayamos aprendido algo sobre lo que cada uno valora, en lugar de haber constatado, una vez más, que los gustos son distintos.`,
       zh:`这一切都不要求意见一致。批评的任务不是制造一致，而是使分歧变得有生产性：让我们在意见不同时对自己看重什么有所认识，而不是再一次确认品味各不相同。`}
    ],
    glossary:[
      {es:'el lugar común', zh:'套话、老生常谈'},
      {es:'de paso', zh:'顺带'},
      {es:'el criterio', zh:'标准'},
      {es:'empíricamente', zh:'在经验上'},
      {es:'al azar', zh:'随意地'},
      {es:'apelar a', zh:'诉诸'},
      {es:'la coherencia', zh:'内在一致性'},
      {es:'explicitar', zh:'明确表述'},
      {es:'el veredicto', zh:'裁决'},
      {es:'dictaminar', zh:'下判词'},
      {es:'reutilizable', zh:'可复用的'},
      {es:'coincidir', zh:'一致、认同'},
      {es:'de antemano', zh:'事先'},
      {es:'clausurar', zh:'封闭'},
      {es:'la unanimidad', zh:'一致'},
      {es:'constatar', zh:'确认、查明'}
    ],
    structures:[
      {es:`es un lugar común que sirve para cerrar discusiones y, de paso, para no examinar ninguno de los criterios`,
       note:`servir para + 不定式 ＝「用于」。de paso 插入表顺带效果。ninguno 在动词后保留否定意义。`},
      {es:`no lo hacemos al azar`,
       note:`lo 回指前面的 discutir sobre gustos，代替整个动词短语。`},
      {es:`en parte porque muchas veces los descubrimos al formularlos`,
       note:`al + 不定式 ＝「在……的时候」。los 回指 los criterios。`},
      {es:`De ahí que la crítica tenga mala reputación.`,
       note:`de ahí que + 虚拟式（tenga）。tener mala reputación ＝「名声不好」。`},
      {es:`el que explica por qué algo funciona o fracasa nos da algo reutilizable`,
       note:`el que ＝「那个……的人」，与 un crítico que 形成对照。`},
      {es:`hacer que el desacuerdo sea productivo`,
       note:`hacer que + 虚拟式（sea）＝「使……成为」。`}
    ],
    questions:[
      {q:'¿Por qué el autor considera falsa la fórmula «sobre gustos no hay nada escrito»?', a:'Porque discutimos sobre gustos continuamente y apelamos a criterios concretos.'},
      {q:'¿Por qué esos criterios rara vez se explicitan?', a:'Porque muchas veces los descubrimos al formularlos.'},
      {q:'¿Qué diferencia hay entre dictaminar y explicar?', a:'Dictaminar no aporta nada; explicar por qué algo funciona o fracasa da algo reutilizable.'},
      {q:'¿Cómo reformula el autor el lugar común?', a:'Que sobre gustos sí hay algo escrito, pero se escribe en el acto de argumentar, no de antemano.'},
      {q:'¿Cuál es la tarea de la crítica según el texto?', a:'Hacer que el desacuerdo sea productivo, no producir unanimidad.'}
    ]
  },
  {level:'B2', title:'「赞」改变了什么', topic:'社交媒体与心理', minutes:6,
    paragraphs:[
      {es:`Cuando apareció el botón de «me gusta», parecía un detalle menor. Bastaba un clic para expresar aprobación, sin escribir nada. Dos décadas después, ese gesto mínimo ha reorganizado buena parte de nuestra vida social.`,
       zh:`当"点赞"按钮出现时，它看起来只是个小细节。只需点一下就能表示赞同，不用写任何字。二十年后，这个极小的动作已经重组了我们社交生活的很大一部分。`},
      {es:`El problema no está en el gesto, sino en lo que mide. Un «me gusta» no distingue entre «me ha hecho pensar» y «lo he visto al pasar». Al reducir toda reacción a una sola cifra, el sistema hace imposible expresar matices, y con el tiempo los usuarios aprenden a producir aquello que genera cifras.`,
       zh:`问题不在于这个动作，而在于它衡量的是什么。一个"赞"并不区分"这让我思考"和"我随手看到了"。当把一切反应都简化为一个数字时，系统就让表达细微差别变得不可能，而随着时间推移，用户学会了去生产能带来数字的东西。`},
      {es:`De ahí surge una paradoja incómoda: cuanto más se optimiza el contenido para ser aprobado, menos cosas interesantes se dicen. Lo que provoca reacciones inmediatas rara vez es lo que resiste un segundo examen; y lo que resiste un segundo examen suele llegar tarde a la conversación.`,
       zh:`由此产生一个令人不适的悖论：内容越是被优化为"讨赞"，说出的有意思的东西就越少。能立刻引发反应的东西，很少经得起再看一遍；而经得起再看一遍的东西，往往在对话中来得太晚。`},
      {es:`Hay quien responde que la crítica es exagerada y que las redes han ampliado el debate público. Es cierto en parte, y conviene no ignorarlo. Pero ampliar el debate y mejorar el debate son dos cosas distintas, y a menudo se confunden para cerrar la discusión antes de haberla tenido.`,
       zh:`有人回应说这种批评夸大了，社交网络扩大了公共讨论。这有部分道理，不应忽视。但扩大讨论和改善讨论是两回事，而人们常常把它们混为一谈，以便在讨论尚未进行之前就把它结束掉。`},
      {es:`Lo que está en discusión, en realidad, no es si las redes son buenas o malas: esa pregunta no admite respuesta útil. Lo que se discute es qué se pierde cuando una sola métrica decide qué merece ser visto, y si estamos dispuestos a aceptar ese precio.`,
       zh:`实际上，争议不在于社交网络是好是坏：这个问题没有有用的答案。争议在于，当单一指标决定什么值得被看见时，我们失去了什么，以及我们是否愿意接受这个代价。`}
    ],
    glossary:[
      {es:'el gesto', zh:'动作、姿态'},
      {es:'la aprobación', zh:'赞同'},
      {es:'reorganizar', zh:'重组'},
      {es:'la cifra', zh:'数字'},
      {es:'el matiz', zh:'细微差别'},
      {es:'optimizar', zh:'优化'},
      {es:'provocar', zh:'引发'},
      {es:'resistir un examen', zh:'经得起审视'},
      {es:'la crítica', zh:'批评'},
      {es:'ampliar', zh:'扩大'},
      {es:'la métrica', zh:'指标'},
      {es:'el precio', zh:'代价'}
    ],
    structures:[
      {es:`Al reducir toda reacción a una sola cifra, el sistema hace imposible expresar matices.`,
       note:`al + 不定式 表「在……时」。reducir A a B ＝「把 A 简化为 B」。hacer imposible + 不定式 ＝「使……不可能」。`},
      {es:`cuanto más se optimiza el contenido para ser aprobado, menos cosas interesantes se dicen`,
       note:`cuanto más… menos… 比例结构。para ser aprobado 是被动不定式表目的。`},
      {es:`lo que provoca reacciones inmediatas rara vez es lo que resiste un segundo examen`,
       note:`lo que… es lo que… 名词性关系从句作主语和表语。rara vez ＝「很少」，位于动词前。`},
      {es:`Hay quien responde que la crítica es exagerada.`,
       note:`hay quien + 陈述式（responde）；若用 hay quienes 则谓语须用复数。`},
      {es:`Lo que está en discusión no es si las redes son buenas o malas.`,
       note:`lo que está en discusión 作主语；si 引导名词性从句作表语（间接疑问）。`}
    ],
    questions:[
      {q:'¿Dónde sitúa el autor el problema, y no dónde?', a:'No en el gesto, sino en lo que mide.'},
      {q:'¿Por qué el sistema hace imposible expresar matices?', a:'Porque reduce toda reacción a una sola cifra.'},
      {q:'¿En qué consiste la paradoja que señala?', a:'Que cuanto más se optimiza el contenido para ser aprobado, menos cosas interesantes se dicen.'},
      {q:'¿Qué distinción hace el autor sobre el debate público?', a:'Que ampliar el debate y mejorar el debate son dos cosas distintas.'}
    ]
  },
  {level:'B2', title:'第一份工作教不了你的东西', topic:'职场与成长', minutes:6,
    paragraphs:[
      {es:`Se repite que la primera experiencia laboral es la más formativa. Es una verdad a medias: enseña mucho sobre cómo funciona una organización concreta y muy poco sobre cómo funcionan las organizaciones en general.`,
       zh:`人们常说第一份工作经历最具塑造性。这是半个真相：它教你很多关于某个具体组织如何运作的东西，却几乎不教任何关于组织一般如何运作的东西。`},
      {es:`Quien aprende en un entorno muy jerárquico concluye que el poder siempre viene de arriba. Quien aprende en uno caótico deduce que la improvisación es la norma. En ambos casos se confunde una costumbre local con una ley de la naturaleza.`,
       zh:`在高度等级化的环境中学习的人会得出结论：权力总是自上而下。在混乱环境中学习的人则推断：即兴发挥是常态。两种情况都把一种地方习惯误认为自然规律。`},
      {es:`Hay un segundo malentendido, más sutil. Los primeros años suelen premiar la disponibilidad: quedarse hasta tarde, aceptar cualquier encargo, responder en minutos. Ese comportamiento funciona, pero no porque sea valioso en sí, sino porque quien aún no sabe nada solo puede ofrecer tiempo.`,
       zh:`还有第二个更微妙的误解。最初几年往往奖励"随叫随到"：加班到很晚、接受任何任务、几分钟内回复。这种行为有效，但不是因为它本身有价值，而是因为还什么都不懂的人只能提供时间。`},
      {es:`El problema aparece cuando esa estrategia se convierte en identidad. Si alguien ha construido su reputación sobre estar siempre disponible, tendrá dificultades para decir no, incluso cuando decir no sea lo profesionalmente correcto.`,
       zh:`当这一策略变成身份认同时，问题就出现了。如果一个人把自己的声誉建立在"永远有空"之上，他就很难说"不"，即便说"不"在专业上才是正确的。`},
      {es:`De ahí que la recomendación más útil para quien empieza no sea trabajar más horas, sino observar de qué depende realmente el prestigio dentro de esa organización. Casi nunca depende de lo que el manual dice, y descubrirlo antes ahorra años de esfuerzo mal dirigido.`,
       zh:`因此，对刚起步的人最有益的建议不是多干几小时，而是观察在那家组织里声望真正取决于什么。它几乎从不取决于手册上写的东西，而早点弄清这一点能省下多年方向错误的努力。`}
    ],
    glossary:[
      {es:'formativo', zh:'有塑造作用的'},
      {es:'la verdad a medias', zh:'半个真相'},
      {es:'jerárquico', zh:'等级化的'},
      {es:'caótico', zh:'混乱的'},
      {es:'deducir', zh:'推断'},
      {es:'la improvisación', zh:'即兴应对'},
      {es:'sutil', zh:'微妙的'},
      {es:'la disponibilidad', zh:'随叫随到'},
      {es:'el encargo', zh:'委派的任务'},
      {es:'la reputación', zh:'声誉'},
      {es:'el prestigio', zh:'声望'},
      {es:'mal dirigido', zh:'方向错误的'}
    ],
    structures:[
      {es:`Es una verdad a medias: enseña mucho sobre cómo funciona una organización concreta y muy poco sobre cómo funcionan en general.`,
       note:`冒号后解释前半句。mucho… y muy poco… 形成对比；cómo 引导名词性从句作 sobre 的宾语。`},
      {es:`no porque sea valioso en sí, sino porque quien aún no sabe nada solo puede ofrecer tiempo`,
       note:`no porque… sino porque… 结构。注意两个 porque 后都用陈述式：这里都不是「否定原因」，而是否定「某个理由成立」并给出真正的理由。`},
      {es:`De ahí que la recomendación más útil no sea trabajar más horas, sino observar de qué depende realmente el prestigio.`,
       note:`de ahí que + 虚拟式（sea）。no… sino… 引出真正的建议。de qué depende ＝「取决于什么」，疑问词引导名词性从句。`},
      {es:`Casi nunca depende de lo que el manual dice.`,
       note:`lo que… dice ＝「手册上所说的」。注意用陈述式 dice，因指实际内容。`}
    ],
    questions:[
      {q:'¿Por qué el autor dice que es «una verdad a medias»?', a:'Porque enseña sobre una organización concreta, no sobre las organizaciones en general.'},
      {q:'¿En qué se confunde una costumbre local con una ley natural?', a:'En concluir que el poder siempre viene de arriba o que la improvisación es la norma.'},
      {q:'¿Por qué funciona la estrategia de la disponibilidad?', a:'No porque sea valiosa en sí, sino porque quien no sabe nada solo puede ofrecer tiempo.'},
      {q:'¿Qué recomienda el autor a quien empieza?', a:'Observar de qué depende realmente el prestigio en esa organización.'}
    ]
  },
  {level:'C1', title:'论妥协的政治', topic:'政治与伦理', minutes:8,
    paragraphs:[
      {es:`En el lenguaje corriente, «compromiso» y «transigir» comparten espacio con «claudicar» y «traicionar». Esta contaminación semántica no es inocente: vuelve sospechoso cualquier acuerdo y favorece a quien nunca necesita acordar nada.`,
       zh:`在日常语言中，"妥协"与"让步"和"屈服""背叛"共享语义空间。这种语义污染并非无辜：它使任何协议都变得可疑，并有利于那些从不需要达成协议的人。`},
      {es:`Conviene, pues, distinguir. Una cosa es renunciar a un principio y otra muy distinta es ceder en su aplicación concreta. Quien sostiene que nunca cederá en nada no está defendiendo una ética más firme: está anunciando que no gobernará, o que gobernará sin contar con nadie.`,
       zh:`因此有必要区分。放弃一项原则是一回事，在它的具体落实上让步是完全另一回事。声称自己绝不在任何事情上让步的人，并非在捍卫更坚定的伦理：他是在宣告自己将不执政，或者将不顾任何人而执政。`},
      {es:`La objeción habitual es que existen límites infranqueables. Es cierto, y precisamente por eso la cuestión relevante no es si hay límites, sino cuáles son y quién los define. Un límite que se proclama para cada negociación no es un límite: es una táctica.`,
       zh:`常见的反驳是存在不可逾越的界限。确实如此，而正因如此，关键问题不在于是否有界限，而在于界限是什么、由谁来界定。在每一场谈判中都宣称的"界限"并不是界限：那是一种策略。`},
      {es:`Hay además un argumento de resultados que suele desestimarse por superficial. Quien nunca pacta puede conservar intacta su coherencia y, al mismo tiempo, dejar el poder en manos de quien no tiene escrúpulos. La pureza intachable y la irrelevancia práctica son, con frecuencia, la misma cosa.`,
       zh:`此外还有一个常被斥为肤浅的结果论论证。从不达成协议的人可以完整保持自身的逻辑一致，同时把权力留在毫无顾忌的人手中。无可指摘的纯粹与实际的无关紧要，往往是同一回事。`},
      {es:`Nada de esto convierte la negociación en una virtud automática. Se puede negociar por convicción o por pereza; se puede ceder en lo accesorio o en lo esencial disfrazándolo de accesorio. La diferencia no está en el hecho de pactar, sino en si uno sabe —y puede explicar— qué ha entregado y por qué.`,
       zh:`这一切都没有使谈判自动成为美德。人可以出于信念去谈判，也可以出于懈怠去谈判；可以在次要问题上让步，也可以把本质问题伪装成次要问题让出去。区别不在于是否达成协议，而在于一个人是否知道——并且能够解释——自己交出了什么、为什么。`},
      {es:`De ahí que la exigencia razonable no sea la intransigencia, sino la contabilidad. Al final de un acuerdo, quien lo firmó debería poder decir sin sonrojarse qué ganó, qué perdió y qué habría sido peor. Si no puede responderse a sí mismo esas tres preguntas, el problema no es que haya cedido: es que no sabía qué estaba haciendo.`,
       zh:`因此合理的要求不是毫不妥协，而是"算得清账"。在一份协议结束时，签署者应当能不愧疚地说出：得到了什么、失去了什么、以及什么本会更糟。如果他不能回答自己这三个问题，问题不在于他让步了，而在于他不知道自己正在做什么。`}
    ],
    glossary:[
      {es:'transigir', zh:'让步、通融'},
      {es:'claudicar', zh:'屈服、变节'},
      {es:'la contaminación semántica', zh:'语义污染'},
      {es:'inocente', zh:'无辜的、无恶意的'},
      {es:'sospechoso', zh:'可疑的'},
      {es:'renunciar a', zh:'放弃'},
      {es:'ceder', zh:'让步'},
      {es:'infranqueable', zh:'不可逾越的'},
      {es:'proclamar', zh:'宣告'},
      {es:'la táctica', zh:'策略'},
      {es:'desestimar', zh:'轻视、不予考虑'},
      {es:'intacto', zh:'完好无损的'},
      {es:'la coherencia', zh:'一贯性'},
      {es:'los escrúpulos', zh:'顾忌、良心不安'},
      {es:'intachable', zh:'无可指摘的'},
      {es:'la intransigencia', zh:'不妥协'},
      {es:'la contabilidad', zh:'算账、交代'},
      {es:'sonrojarse', zh:'脸红、羞愧'}
    ],
    structures:[
      {es:`Una cosa es renunciar a un principio y otra muy distinta es ceder en su aplicación concreta.`,
       note:`una cosa es… y otra muy distinta es… 是常用的对比句式，前后用不定式并列。`},
      {es:`la cuestión relevante no es si hay límites, sino cuáles son y quién los define`,
       note:`si 引导间接疑问作表语；cuáles 与 quién 并列引导另一名词性从句，语序为疑问词前置。`},
      {es:`Quien nunca pacta puede conservar intacta su coherencia y, al mismo tiempo, dejar el poder en manos de quien no tiene escrúpulos.`,
       note:`quien + 陈述式 表泛指。conservar intacta su coherencia：形容词 intacta 作宾语补足语，与 coherencia 一致。en manos de quien… 中 quien 作前置词宾语。`},
      {es:`se puede ceder en lo accesorio o en lo esencial disfrazándolo de accesorio`,
       note:`disfrazándolo 是副动词，与主句主语同指；lo 回指 lo esencial。disfrazar A de B ＝「把 A 伪装成 B」。`},
      {es:`si uno sabe —y puede explicar— qué ha entregado y por qué`,
       note:`破折号内为插入成分。qué ha entregado 与 por qué 并列作 saber 的宾语从句。`}
    ],
    questions:[
      {q:'¿A quién favorece, según el autor, la contaminación semántica del término «compromiso»?', a:'A quien nunca necesita acordar nada.'},
      {q:'¿Qué distinción introduce el autor?', a:'Entre renunciar a un principio y ceder en su aplicación concreta.'},
      {q:'¿Por qué un límite proclamado en cada negociación no es un límite?', a:'Porque entonces es una táctica, no un límite.'},
      {q:'¿Qué relación establece entre pureza e irrelevancia?', a:'Que la pureza intachable y la irrelevancia práctica suelen ser la misma cosa.'},
      {q:'¿Cuál es la exigencia razonable que propone?', a:'La contabilidad: poder decir qué se ganó, qué se perdió y qué habría sido peor.'}
    ]
  },
  {level:'C1', title:'隐私是一种过时的特权吗', topic:'科技与权利', minutes:8,
    paragraphs:[
      {es:`Se repite que la privacidad ha muerto y que quien se preocupa por ella es un ingenuo o alguien con algo que esconder. Ambas fórmulas funcionan como cierre de conversación, y ambas merecen el examen que pretenden evitar.`,
       zh:`人们反复说隐私已死，关心隐私的人要么天真，要么心里有鬼。这两种说法都在充当终止对话的角色，而两者都值得接受它们试图回避的审视。`},
      {es:`Hay un malentendido inicial: confundir privacidad con secreto. Lo privado no es lo que se oculta, sino lo que se decide no compartir. Un domicilio no es un secreto, y sin embargo la posibilidad de cerrar la puerta resulta indispensable para vivir.`,
       zh:`有一个初始误解：把隐私与秘密混为一谈。私密的不是被隐藏的东西，而是决定不分享的东西。住处不是秘密，然而能够关上门对生活而言不可或缺。`},
      {es:`La segunda fórmula es más interesante porque contiene una verdad incómoda. Para quien dispone de poder —económico, político o simplemente social—, la visibilidad es una oportunidad. Para quien carece de él, la visibilidad suele ser un riesgo. Decir por eso que la privacidad solo interesa a quien tiene algo que ocultar equivale a decir que solo los poderosos pueden permitirse ser transparentes.`,
       zh:`第二种说法更有意思，因为它包含一个令人不适的真相。对拥有权力的人——经济的、政治的，或者仅仅是社会性的——可见度是机会。对缺乏权力的人，可见度往往是风险。因此说只有心里有鬼的人才在意隐私，等于是说只有有权势的人才负担得起透明。`},
      {es:`De ahí que el debate no sea simétrico. Cuando se argumenta que «ya no hay nada privado» y que conviene adaptarse, se está proponiendo, en la práctica, que un determinado reparto de exposición quede fijado para siempre. Y ese reparto, hoy, no lo negocia el usuario: lo fijan quienes recogen los datos.`,
       zh:`因此这场辩论并不对称。当有人说"已经没有什么私密可言"、应当适应时，实际上是在建议把某种特定的暴露分配永久固定下来。而这一分配在今天并不是由用户协商的：它由收集数据的人决定。`},
      {es:`Cabe objetar que la transparencia total beneficiaría a todos, porque quien nada hace nada teme. El argumento se sostiene solo si se presupone que el sistema que observa es imparcial, que sus criterios son públicos y que quien los aplica responde ante alguien. Ninguna de las tres condiciones se cumple por defecto, y las tres son históricamente frágiles.`,
       zh:`可以反驳说，完全的透明会让所有人受益，因为"没做亏心事不怕鬼敲门"。这个论证只有在假设观察系统是公正的、其标准是公开的、执行者需向某人负责时才成立。而这三个条件默认都不成立，且历史上都很脆弱。`},
      {es:`La cuestión, entonces, no es si tenemos algo que esconder, sino quién está mirando, con qué reglas y con qué límites. Reducirla a la primera pregunta es la manera más eficaz de que nunca lleguemos a la segunda.`,
       zh:`因此问题不在于我们是否有什么要隐藏，而在于谁在看、依据什么规则、受什么限制。把它简化为第一个问题，是最有效地让我们永远问不出第二个问题的方式。`}
    ],
    glossary:[
      {es:'el ingenuo', zh:'天真的人'},
      {es:'el cierre de conversación', zh:'终止对话的手法'},
      {es:'el examen', zh:'审视'},
      {es:'ocultar', zh:'隐藏'},
      {es:'el domicilio', zh:'住所'},
      {es:'indispensable', zh:'不可或缺的'},
      {es:'la visibilidad', zh:'可见度'},
      {es:'carecer de', zh:'缺乏'},
      {es:'equivaler a', zh:'等于'},
      {es:'simétrico', zh:'对称的'},
      {es:'el reparto', zh:'分配'},
      {es:'la exposición', zh:'暴露'},
      {es:'quedar fijado', zh:'被固定下来'},
      {es:'presuponer', zh:'预设'},
      {es:'imparcial', zh:'公正的'},
      {es:'frágil', zh:'脆弱的'}
    ],
    structures:[
      {es:`ambas merecen el examen que pretenden evitar`,
       note:`关系从句用陈述式（pretenden），因指实际发生的情况。evitar 的宾语由关系代词 que 承担。`},
      {es:`Lo privado no es lo que se oculta, sino lo que se decide no compartir.`,
       note:`no… sino… 结构；lo privado 与 lo que + 从句 均为名词化表达，作主语与表语。`},
      {es:`Decir por eso que… equivale a decir que…`,
       note:`不定式作主语；equivaler a + 不定式 ＝「等于说……」。`},
      {es:`se está proponiendo, en la práctica, que un determinado reparto quede fijado`,
       note:`proponer que + 虚拟式（quede）。estar + 副动词 表进行中的动作，此处指「（这样做）等于在提议」。`},
      {es:`El argumento se sostiene solo si se presupone que el sistema es imparcial.`,
       note:`sostenerse ＝「站得住脚」。solo si ＝「只有如果」，后面用陈述式（真实条件的限定）。`},
      {es:`Reducirla a la primera pregunta es la manera más eficaz de que nunca lleguemos a la segunda.`,
       note:`reducirla 中 la 回指 la cuestión。manera de que + 虚拟式（lleguemos）＝「……的方式」。`}
    ],
    questions:[
      {q:'¿Qué malentendido inicial señala el autor?', a:'Confundir privacidad con secreto.'},
      {q:'¿Por qué la segunda fórmula contiene una verdad incómoda?', a:'Porque la visibilidad es oportunidad para quien tiene poder y riesgo para quien no lo tiene.'},
      {q:'¿Por qué el debate no es simétrico?', a:'Porque el reparto de exposición no lo negocia el usuario, lo fijan quienes recogen los datos.'},
      {q:'¿Qué tres condiciones presupone el argumento de la transparencia total?', a:'Que el sistema sea imparcial, que sus criterios sean públicos y que quien los aplica responda ante alguien.'},
      {q:'¿Cuál es la cuestión de fondo según el texto?', a:'Quién está mirando, con qué reglas y con qué límites.'}
    ]
  },
  {level:'C2', title:'论无用的必要性', topic:'文化与价值', minutes:9,
    paragraphs:[
      {es:`Ninguna sociedad ha logrado jamás justificar del todo aquello que no sirve para nada, y ninguna ha dejado de producirlo. La tensión entre ambas constataciones es, quizá, uno de los rasgos más persistentes de la cultura humana.`,
       zh:`没有任何社会曾完全证明过那些"毫无用处"之物是正当的，也没有任何社会停止过生产它们。这两项事实之间的张力，或许是人类文化最持久的特征之一。`},
      {es:`La dificultad estriba en que el lenguaje de la utilidad es devorador. Preguntado para qué sirve un poema, uno puede responder que para nada, y con ello creer haber zanjado la cuestión; pero la pregunta misma ya había establecido el marco en el que solo ciertas respuestas cuentan como respuestas.`,
       zh:`困难在于功利语言具有吞噬性。被问及一首诗有什么用，人可以回答"没什么用"，并以为这样就了结了问题；但这个问题本身已经确立了那个只有某些回答才算回答的框架。`},
      {es:`Hay una salida habitual, y algo tramposa: reivindicar lo inútil por sus efectos útiles. Se defiende la música porque mejora el rendimiento cognitivo, la literatura porque desarrolla la empatía, el ocio porque aumenta la productividad posterior. Los beneficios son reales; el razonamiento, sin embargo, concede de antemano lo que pretendía discutir.`,
       zh:`有一种常见而略显取巧的出路：以无用之物的有用效果来为它辩护。人们说音乐好是因为它提升认知表现，文学好是因为它培养共情，休闲好是因为它提高之后的生产率。这些益处是真实的；然而这个推理预先让出了它本想争论的那个前提。`},
      {es:`Pues si el valor de esas prácticas dependiera de sus consecuencias, bastaría con sustituirlas por medios más eficientes de obtener las mismas consecuencias. Quien defiende la poesía porque reduce el estrés debería aceptar, si es coherente, una pastilla que lo reduzca mejor.`,
       zh:`因为如果这些实践的价值取决于它们的后果，那么用更高效的手段取得同样后果就足够了。若有人因为诗能减压而为它辩护，那么只要他逻辑一致，就应当接受一颗减得更好的药片。`},
      {es:`Cabe sospechar que esa defensa no la sostiene nadie de verdad, y que su función es distinta: permitir que lo inútil sobreviva en un entorno que lo interroga. Es una estratagema comprensible, aunque tiene un coste, porque obliga a justificar en un idioma que nunca concederá la razón del todo.`,
       zh:`可以怀疑，这种辩护其实没有人真正坚持，而它的功能另有其用：让无用之物在一个不断盘问它的环境中存活下来。这是一种可以理解的权宜之计，尽管有代价，因为它迫使人用一种永远不会完全认同的语调来为自己的主张辩护。`},
      {es:`Quizá el error consista en exigir una justificación donde solo cabe una descripción. Decir qué se hace con un poema, o qué le ocurre a quien lo lee, no es defenderlo: es señalar un hecho. Y hay hechos que no necesitan defensa, sino únicamente que no se los aplaste preguntándoles para qué.`,
       zh:`也许错误在于，在一个只能给出描述的地方要求给出正当性证明。说明人们拿一首诗做什么，或者读它的人身上发生了什么，并不是在为它辩护：而是在指出一个事实。有些事实不需要辩护，只需要不被"这有什么用"的追问压碎。`}
    ],
    glossary:[
      {es:'justificar', zh:'证明正当'},
      {es:'la constatación', zh:'确认的事实'},
      {es:'persistente', zh:'持久的'},
      {es:'estribar en', zh:'在于'},
      {es:'devorador', zh:'吞噬性的'},
      {es:'zanjado', zh:'已了结的'},
      {es:'el marco', zh:'框架'},
      {es:'tramposo', zh:'取巧的、作弊的'},
      {es:'reivindicar', zh:'为……正名、主张'},
      {es:'el rendimiento cognitivo', zh:'认知表现'},
      {es:'conceder', zh:'让出、承认'},
      {es:'de antemano', zh:'预先'},
      {es:'coherente', zh:'逻辑一致的'},
      {es:'sospechar', zh:'怀疑'},
      {es:'la estratagema', zh:'权宜之计、计谋'},
      {es:'el coste', zh:'代价'},
      {es:'aplastar', zh:'压碎'}
    ],
    structures:[
      {es:`Preguntado para qué sirve un poema, uno puede responder que para nada.`,
       note:`Preguntado 是过去分词独立结构，相当于「当被问及……时」，其隐含主语与主句主语一致。para qué sirve 为间接疑问从句。`},
      {es:`la pregunta misma ya había establecido el marco en el que solo ciertas respuestas cuentan como respuestas`,
       note:`过去完成时表先于过去动作。en el que 引导关系从句修饰 el marco。contar como ＝「算作」。`},
      {es:`el razonamiento concede de antemano lo que pretendía discutir`,
       note:`conceder ＝「让出（论点）」，此处指「预设了本应争论的前提」。lo que pretendía discutir ＝「它本想争论的东西」。`},
      {es:`Pues si el valor de esas prácticas dependiera de sus consecuencias, bastaría con sustituirlas por medios más eficientes.`,
       note:`非现实条件句：si + 虚拟式过去时（dependiera）→ 条件式（bastaría）。bastar con + 不定式。sustituir A por B。`},
      {es:`Quien defiende la poesía porque reduce el estrés debería aceptar, si es coherente, una pastilla que lo reduzca mejor.`,
       note:`quien + 陈述式 表泛指。debería 为条件式表建议。si es coherente 用陈述式（对读者是否一致的判断）。una pastilla que lo reduzca mejor 用虚拟式，因该先行词为非确指的存在。`},
      {es:`Quizá el error consista en exigir una justificación donde solo cabe una descripción.`,
       note:`quizá + 虚拟式（consista）。caber ＝「容得下、可以有」。donde 引导关系从句修饰隐含的地点。`}
    ],
    questions:[
      {q:'¿Qué tensión señala el autor al comienzo?', a:'Que ninguna sociedad ha justificado del todo lo inútil y ninguna ha dejado de producirlo.'},
      {q:'¿Por qué el lenguaje de la utilidad es «devorador»?', a:'Porque la pregunta misma establece el marco en el que solo ciertas respuestas cuentan.'},
      {q:'¿Qué defecto tiene la defensa de lo inútil por sus efectos útiles?', a:'Que concede de antemano lo que pretendía discutir.'},
      {q:'¿Qué implicaría ser coherente con ese razonamiento?', a:'Aceptar que bastaría sustituir esas prácticas por medios más eficientes.'},
      {q:'¿En qué consistiría el error según el autor?', a:'En exigir una justificación donde solo cabe una descripción.'}
    ]
  },
  {level:'B2', title:'为什么好建议常常没用', topic:'决策与行为', minutes:6,
    paragraphs:[
      {es:`Todos hemos dado consejos que nos parecían evidentes y hemos visto cómo el otro los ignoraba sin siquiera discutirlos. La reacción habitual es atribuirlo a la terquedad ajena. Rara vez es eso.`,
       zh:`我们都给过自己觉得显而易见的建议，也见过对方连讨论都不讨论就把它忽略掉。常见的反应是把它归因于别人的固执。但很少是这个原因。`},
      {es:`El primer motivo es que un consejo resuelve el problema de quien lo da, no el de quien lo recibe. Quien aconseja se sitúa fuera de la situación y, desde ahí, todo parece ordenado; quien la vive tiene que lidiar además con el miedo, con el coste social y con lo que perderá si se equivoca.`,
       zh:`第一个原因是建议解决的是提建议者的问题，而不是接受者的。提建议的人置身情境之外，从那里看一切都井然有序；而身处其中的人还要应对恐惧、社会代价，以及一旦出错会失去什么。`},
      {es:`El segundo es más incómodo: la mayoría de los consejos presuponen una capacidad que el otro no necesariamente tiene. Decirle a alguien «pon límites» es como decirle a quien no sabe nadar que nade más rápido. La instrucción es correcta y completamente inútil al mismo tiempo.`,
       zh:`第二个更令人不适：大多数建议预设了对方未必具备的能力。对某人说"设好界限"，就像对不会游泳的人说"游快点"。这个指令是正确的，同时也完全没用。`},
      {es:`De ahí que los consejos que funcionan sean casi siempre más pequeños y más concretos de lo que a uno le gustaría. No «sé más organizado», sino «mañana, antes de abrir el correo, escribe tres cosas». Lo específico es menos elegante y mucho más eficaz, porque no exige una transformación previa.`,
       zh:`因此真正有效的建议，几乎总是比人希望的更小、更具体。不是"更有条理些"，而是"明天开邮箱之前，写下三件事"。具体的做法不那么漂亮，却有效得多，因为它不要求先完成一次转变。`},
      {es:`Queda un último malentendido, quizá el más persistente: creer que el valor del consejo se mide por su veracidad. Casi nunca. Se mide por si el otro puede ejecutarlo mañana. Un consejo verdadero que nadie puede seguir es, en la práctica, una opinión sobre uno mismo disfrazada de ayuda.`,
       zh:`还有最后一个误解，或许是最持久的：认为建议的价值由它的正确性衡量。几乎从不是。它由对方明天能否执行来衡量。一个正确却没人能遵循的建议，在实践中不过是一段伪装成帮助的自我陈述。`}
    ],
    glossary:[
      {es:'la terquedad', zh:'固执'},
      {es:'la terquedad ajena', zh:'别人的固执'},
      {es:'evidente', zh:'显而易见的'},
      {es:'lidiar con', zh:'应对、周旋'},
      {es:'el coste social', zh:'社会代价'},
      {es:'presuponer', zh:'预设'},
      {es:'la capacidad', zh:'能力'},
      {es:'la instrucción', zh:'指示、教导'},
      {es:'concreto', zh:'具体的'},
      {es:'la transformación previa', zh:'先行的转变'},
      {es:'persistente', zh:'持久的'},
      {es:'la veracidad', zh:'真实性'},
      {es:'ejecutar', zh:'执行'},
      {es:'disfrazado de', zh:'伪装成'}
    ],
    structures:[
      {es:`hemos visto cómo el otro los ignoraba sin siquiera discutirlos`,
       note:`cómo 引导名词性从句作 ver 的宾语。sin siquiera + 不定式 ＝「甚至连……都没有」。los 回指 los consejos。`},
      {es:`Quien aconseja se sitúa fuera de la situación y, desde ahí, todo parece ordenado.`,
       note:`quien + 陈述式 表泛指。desde ahí 指「从那个位置看」。注意前后是两个独立分句，用 y 连接。`},
      {es:`Decirle a alguien «pon límites» es como decirle a quien no sabe nadar que nade más rápido.`,
       note:`es como + 不定式 表类比。a quien no sabe nadar 中 quien 引导名词性关系从句作间接宾语。nade 用虚拟式（命令内容嵌入从句）。`},
      {es:`No «sé más organizado», sino «mañana, antes de abrir el correo, escribe tres cosas».`,
       note:`no… sino… 对比两种表述，两者均为直接引语形式，故保留原命令式。`},
      {es:`Se mide por si el otro puede ejecutarlo mañana.`,
       note:`medirse por ＝「以……衡量」。por si 在此不是「以防」，而是前置词 por + 连词 si，意为「依据是否……」。`}
    ],
    questions:[
      {q:'¿A qué se atribuye habitualmente que el otro ignore un consejo, y qué opina el autor?', a:'Se atribuye a la terquedad ajena; el autor dice que rara vez es eso.'},
      {q:'¿Por qué un consejo resuelve el problema de quien lo da?', a:'Porque quien aconseja se sitúa fuera de la situación, donde todo parece ordenado.'},
      {q:'¿Qué presuponen la mayoría de los consejos?', a:'Una capacidad que el otro no necesariamente tiene.'},
      {q:'¿Cómo son los consejos que funcionan?', a:'Más pequeños y concretos, porque no exigen una transformación previa.'},
      {q:'¿Cómo se mide el valor de un consejo según el autor?', a:'Por si el otro puede ejecutarlo mañana, no por su veracidad.'}
    ]
  },
  {level:'B2', title:'度假为何让人更累', topic:'生活方式', minutes:6,
    paragraphs:[
      {es:`Hay una escena repetida: alguien vuelve de vacaciones y confiesa, con una mezcla de vergüenza y orgullo, que necesita descansar del descanso. La frase es graciosa y esconde un problema real de diseño.`,
       zh:`有一个反复出现的场景：有人度假回来，带着羞耻与骄傲的混合心情承认，自己需要从休息中休息一下。这句话很好笑，却藏着一个真实的设计问题。`},
      {es:`El primer error es tratar las vacaciones como un proyecto. Se planifican visitas, se reservan restaurantes, se calculan trayectos. Todo eso tiene su lógica, pero convierte once días en una lista de tareas con fotografías, y las listas de tareas, por agradables que sean, no descansan.`,
       zh:`第一个错误是把假期当成一个项目。规划参观、预订餐厅、计算路程。这一切都有其道理，却把十一天变成了一份带照片的任务清单，而任务清单无论多么愉快，都不会让人休息。`},
      {es:`El segundo error es más profundo: usar las vacaciones para compensar un año mal organizado. Quien trabaja doce horas diarias durante once meses no se repara en dos semanas, del mismo modo que no se cura una fractura con un día de reposo.`,
       zh:`第二个错误更深：用假期去补偿一个组织糟糕的年份。每天工作十二小时持续十一个月的人，两周是恢复不过来的，就像骨折不能靠休息一天治好。`},
      {es:`A esto se añade la presión de aprovechar. Como el tiempo libre es escaso y caro, se exige que sea memorable, y esa exigencia produce exactamente lo contrario: la sensación constante de no estar haciéndolo bien.`,
       zh:`此外还有"要充分利用"的压力。因为闲暇时间稀少且昂贵，人们就要求它必须令人难忘，而这一要求恰恰产生了相反的结果：一种持续的"自己没做对"的感觉。`},
      {es:`Quizá la conclusión sea modesta y poco vendible: no hay vacaciones capaces de arreglar un año, y el descanso verdadero se parece menos a una experiencia intensa que a una serie de días sin nada pendiente. Lo cual, dicho así, suena aburridísimo, y probablemente sea la señal de que vamos por buen camino.`,
       zh:`也许结论既平常又不好卖：没有哪种假期能修补一整年，而真正的休息与其说像一次强烈体验，不如说像一连串没有任何待办事项的日子。这话听起来无聊透顶——而这大概正是我们走对了路的信号。`}
    ],
    glossary:[
      {es:'la escena', zh:'场景'},
      {es:'la vergüenza', zh:'羞耻'},
      {es:'esconder', zh:'隐藏'},
      {es:'el trayecto', zh:'路程'},
      {es:'la lista de tareas', zh:'任务清单'},
      {es:'compensar', zh:'补偿'},
      {es:'reparar', zh:'修复、恢复'},
      {es:'la fractura', zh:'骨折'},
      {es:'el reposo', zh:'静养'},
      {es:'aprovechar', zh:'充分利用'},
      {es:'memorable', zh:'难忘的'},
      {es:'la exigencia', zh:'要求'},
      {es:'pendiente', zh:'待办的'},
      {es:'vendible', zh:'好卖的、受欢迎的'}
    ],
    structures:[
      {es:`confiesa, con una mezcla de vergüenza y orgullo, que necesita descansar del descanso`,
       note:`插入语用逗号隔开。descansar del descanso 是刻意的重复修辞（同源宾语式）。necesitar 后接陈述式。`},
      {es:`las listas de tareas, por agradables que sean, no descansan`,
       note:`por + 形容词 + que + 虚拟式 ＝「无论多么……」。agradables 与 listas 保持阴性复数一致。`},
      {es:`no se repara en dos semanas, del mismo modo que no se cura una fractura con un día de reposo`,
       note:`del mismo modo que 引出类比。两处 se 均为被动 se 结构，主语为「人」。`},
      {es:`no hay vacaciones capaces de arreglar un año`,
       note:`no hay + 名词 ＝「没有」。capaces de + 不定式 作后置定语。`},
      {es:`lo cual, dicho así, suena aburridísimo`,
       note:`lo cual 回指前句整句内容。dicho así 为过去分词插入语。aburridísimo 为绝对最高级（-ísimo）。`}
    ],
    questions:[
      {q:'¿Cuál es el primer error que señala el texto?', a:'Tratar las vacaciones como un proyecto con listas de tareas.'},
      {q:'¿Por qué dos semanas no reparan a quien trabaja doce horas diarias?', a:'Porque equivale a querer curar una fractura con un día de reposo.'},
      {q:'¿Qué efecto produce la presión de aprovechar?', a:'La sensación constante de no estar haciéndolo bien.'},
      {q:'¿A qué se parece el descanso verdadero según el autor?', a:'A una serie de días sin nada pendiente, más que a una experiencia intensa.'}
    ]
  },
  {level:'C1', title:'论责任与因果的错位', topic:'伦理与法律', minutes:8,
    paragraphs:[
      {es:`Buena parte de nuestras intuiciones morales presuponen que quien causa un daño es quien debe responder por él. La fórmula funciona en los casos simples y se rompe en cuanto intervienen la cadena de consecuencias y la división del trabajo.`,
       zh:`我们许多道德直觉都预设：造成损害的人应当为之负责。这个公式在简单情形下可行，一旦牵涉后果链条与分工，就会崩塌。`},
      {es:`Considérese un accidente evitables por cinco decisiones distintas, cada una tomada por una persona distinta en un momento distinto. Ninguna de ellas, por separado, habría bastado para producirlo; todas juntas lo hicieron inevitable. ¿A quién se atribuye la responsabilidad?`,
       zh:`设想一场事故，本可由五个不同决定避免，每个决定由不同的人在不同时刻做出。其中任何一个单独都不足以造成它；合在一起却使之不可避免。责任该归于谁？`},
      {es:`La respuesta jurídica suele ser repartirla. La respuesta moral es más incómoda, porque en estos casos la responsabilidad se diluye sin desaparecer: todos contribuyeron y ninguno se siente autor del resultado. Esa es precisamente la condición que hace posible la irresponsabilidad a gran escala.`,
       zh:`法律上的回答通常是分摊。道德上的回答更令人不适，因为在这类情形中责任被稀释却不消失：每个人都出了一份力，而没有人觉得自己是结果作者。而这恰恰是使大规模不负责成为可能的条件。`},
      {es:`De ahí que muchas catástrofes no se deban a maldad ni a negligencia flagrante, sino a una arquitectura en la que cada paso es defendible. Nadie quería el resultado y nadie hizo nada que, aislado, resultara condenable. El daño emerge de la combinación.`,
       zh:`因此许多灾难并非源于恶意或明显的疏忽，而是源于一种每一步都站得住脚的架构。没有人想要那个结果，也没有人做了任何孤立来看应受谴责的事。损害是从组合中涌现的。`},
      {es:`Cabe objetar que esto equivale a disolver la culpa y, con ella, la posibilidad de exigir cambios. La objeción es seria y merece respuesta: distinguir responsabilidad causal de responsabilidad por el diseño. Quien no causó el daño puede seguir siendo responsable de haber construido un sistema donde el daño era previsible.`,
       zh:`有人会反驳说，这等于消解罪责，进而消解要求改变的可能。这个反驳很严肃，值得回应：把因果责任与设计责任区分开。没有造成损害的人，仍可能对构建了一个损害可预见的系统负有责任。`},
      {es:`Esta distinción tiene consecuencias prácticas. Si solo se persigue al último eslabón, el sistema se reproduce intacto; si se examina el diseño, se puede intervenir antes de la próxima catástrofe. Y exige una virtud poco frecuente: renunciar a la satisfacción de encontrar a un culpable identificable.`,
       zh:`这一区分有实际后果。如果只追究最后一环，系统会原封不动地复制自身；如果审视设计，就能在下一次灾难之前介入。而它要求一种罕见的德性：放弃找到某个可指认的罪人所带来的满足感。`}
    ],
    glossary:[
      {es:'la intuición moral', zh:'道德直觉'},
      {es:'el daño', zh:'损害'},
      {es:'responder por', zh:'为……负责'},
      {es:'la cadena de consecuencias', zh:'后果链条'},
      {es:'la división del trabajo', zh:'分工'},
      {es:'evitable', zh:'可避免的'},
      {es:'la responsabilidad', zh:'责任'},
      {es:'repartir', zh:'分摊'},
      {es:'diluirse', zh:'被稀释'},
      {es:'la negligencia', zh:'疏忽'},
      {es:'flagrante', zh:'明显的、现行的'},
      {es:'la arquitectura', zh:'架构'},
      {es:'condenable', zh:'应受谴责的'},
      {es:'emerger', zh:'涌现'},
      {es:'la culpa', zh:'罪责'},
      {es:'previsible', zh:'可预见的'},
      {es:'el eslabón', zh:'环节'},
      {es:'intacto', zh:'原封不动的'}
    ],
    structures:[
      {es:`Considérese un accidente evitable por cinco decisiones distintas.`,
       note:`Considérese 是命令式第三人称的自复形式，用于学术文本中提出假设（「设想」）。evitable por ＝「本可由……避免的」。`},
      {es:`Ninguna de ellas, por separado, habría bastado para producirlo; todas juntas lo hicieron inevitable.`,
       note:`条件式完成时 habría bastado 表未实现的可能性。分号连接对比的两个分句。`},
      {es:`Esa es precisamente la condición que hace posible la irresponsabilidad a gran escala.`,
       note:`hacer posible + 名词 ＝「使……成为可能」，宾语后置以避免过长。`},
      {es:`no se deban a maldad ni a negligencia flagrante, sino a una arquitectura en la que cada paso es defendible`,
       note:`deberse a ＝「源于」。ni… ni… 并列否定。en la que 引导关系从句修饰 arquitectura。`},
      {es:`distinguir responsabilidad causal de responsabilidad por el diseño`,
       note:`distinguir A de B ＝「把 A 与 B 区分开」。por el diseño 表「就设计而言」。`},
      {es:`exige una virtud poco frecuente: renunciar a la satisfacción de encontrar a un culpable identificable`,
       note:`renunciar a + 名词 ＝「放弃」。encontrar a un culpable：指人的直接宾语需加 a。`}
    ],
    questions:[
      {q:'¿Qué presuponen nuestras intuiciones morales según el texto?', a:'Que quien causa un daño es quien debe responder por él.'},
      {q:'¿Por qué la respuesta moral es más incómoda que la jurídica?', a:'Porque la responsabilidad se diluye sin desaparecer: todos contribuyeron y ninguno se siente autor.'},
      {q:'¿A qué se deben muchas catástrofes según el autor?', a:'A una arquitectura en la que cada paso es defendible, no a maldad ni negligencia flagrante.'},
      {q:'¿Qué distinción propone para responder a la objeción?', a:'La de responsabilidad causal y responsabilidad por el diseño.'},
      {q:'¿Qué consecuencia práctica tiene la distinción?', a:'Permite intervenir sobre el diseño antes de la próxima catástrofe, en vez de perseguir solo al último eslabón.'}
    ]
  },
  {level:'C1', title:'为什么专家预测常常失败', topic:'认知与判断', minutes:8,
    paragraphs:[
      {es:`La investigación sobre predicciones ha producido un resultado incómodo y persistente: en muchos dominios, los expertos no superan a modelos estadísticos simples, y en algunos rinden peor que el azar informado.`,
       zh:`关于预测的研究产生了一个令人不适而持久的结论：在许多领域，专家并不胜过简单的统计模型，在某些领域甚至不如有信息基础的随机判断。`},
      {es:`La explicación más difundida es la falta de datos. Es insuficiente. Los expertos suelen disponer de más información que nadie y, precisamente por eso, están más expuestos a un sesgo característico: la confianza crece con la cantidad de información mucho más rápido que la precisión.`,
       zh:`最流行的解释是数据不足。这不够。专家往往掌握比任何人都多的信息，而正因如此，他们更容易受到一种典型偏差的影响：信心的增长速度远快于准确度的增长速度。`},
      {es:`Hay un segundo factor, menos discutido: el experto tiene incentivos para no equivocarse de manera visible, lo que favorece las predicciones vagas. Un pronóstico que admite cualquier desenlace nunca queda desmentido, y por eso abundan los diagnósticos lo bastante ambiguos como para sobrevivir a los hechos.`,
       zh:`还有第二个较少被讨论的因素：专家有不"明显出错"的动机，这有利于做出模糊的预测。一个能容纳任何结局的预判永远不会被推翻，因此充满了模糊到足以在事实面前存活下来的判断。`},
      {es:`El tercer factor es de orden narrativo. Explicar requiere una historia coherente, y las historias exigen causas identificables; los fenómenos complejos, en cambio, suelen depender de la interacción de factores que no se pueden separar sin destruir el fenómeno. La demanda de explicación empuja hacia relatos más ordenados que la realidad.`,
       zh:`第三个因素属于叙事层面。解释需要一段连贯的故事，而故事要求有可指认的原因；而复杂现象往往取决于那些一旦分离就会破坏现象本身的因素之间的相互作用。对解释的需求把人们推向比现实更有序的叙述。`},
      {es:`Nada de esto demuestra que el conocimiento experto sea inútil, y conviene decirlo antes de que alguien lo concluya por su cuenta. Demuestra algo más limitado y más exigente: que el conocimiento experto es valioso para delimitar posibilidades y muy poco fiable para asignarles probabilidades concretas.`,
       zh:`这一切都没有证明专家知识无用，这句话应当先说出来，免得有人自行得出那个结论。它证明的是一件更有限也更严格的事：专家知识在界定可能性范围时很有价值，而在为它们赋予具体概率时极不可靠。`},
      {es:`De ahí que la práctica más razonable no sea prescindir de los expertos, sino exigirles lo que pueden dar y no lo que se les pide habitualmente: escenarios con condiciones explícitas, en lugar de pronósticos cerrados que nadie podrá comprobar hasta que sea tarde.`,
       zh:`因此最合理的做法不是弃用专家，而是向他们索取他们能给出的东西，而不是通常被要求的东西：带有明确条件的各种情景，而不是直到为时已晚才无人能核实的封闭式预测。`}
    ],
    glossary:[
      {es:'la predicción', zh:'预测'},
      {es:'el dominio', zh:'领域'},
      {es:'el azar informado', zh:'有信息基础的随机'},
      {es:'difundido', zh:'流行的、广为传播的'},
      {es:'el sesgo', zh:'偏差'},
      {es:'la precisión', zh:'准确度'},
      {es:'el incentivo', zh:'动机'},
      {es:'vago', zh:'模糊的'},
      {es:'el pronóstico', zh:'预判'},
      {es:'el desenlace', zh:'结局'},
      {es:'desmentir', zh:'推翻、否定'},
      {es:'ambiguo', zh:'模棱两可的'},
      {es:'narrativo', zh:'叙事的'},
      {es:'la interacción', zh:'相互作用'},
      {es:'delimitar', zh:'界定'},
      {es:'asignar', zh:'赋予'},
      {es:'prescindir de', zh:'不用、舍弃'},
      {es:'cerrado', zh:'封闭的、确定的'}
    ],
    structures:[
      {es:`los expertos no superan a modelos estadísticos simples, y en algunos rinden peor que el azar informado`,
       note:`superar a ＝「胜过」。rendir ＝「表现、产出」。peor que 比较。`},
      {es:`la confianza crece con la cantidad de información mucho más rápido que la precisión`,
       note:`crecer con ＝「随……增长」。mucho más rápido que 修饰比较，表差距显著。`},
      {es:`el experto tiene incentivos para no equivocarse de manera visible`,
       note:`tener incentivos para + 不定式。equivocarse 的否定形式作「不犯错」。`},
      {es:`los fenómenos complejos suelen depender de la interacción de factores que no se pueden separar sin destruir el fenómeno`,
       note:`sin + 不定式 表条件（「若不……」）。较长的关系从句后置，避免打断主句。`},
      {es:`conviene decirlo antes de que alguien lo concluya por su cuenta`,
       note:`antes de que + 虚拟式（concluya）。por su cuenta ＝「自行、独自」。`},
      {es:`De ahí que la práctica más razonable no sea prescindir de los expertos, sino exigirles lo que pueden dar.`,
       note:`de ahí que + 虚拟式（sea）。no… sino… 对比。exigirles 中 les 为间接宾语（向他们索取）。`}
    ],
    questions:[
      {q:'¿Por qué es insuficiente la explicación de la falta de datos?', a:'Porque los expertos suelen tener más información y, por eso, la confianza crece más rápido que la precisión.'},
      {q:'¿Qué incentivo favorece las predicciones vagas?', a:'El de no equivocarse de manera visible.'},
      {q:'¿Por qué el factor narrativo empuja hacia relatos ordenados?', a:'Porque explicar exige causas identificables, y los fenómenos complejos dependen de interacciones inseparables.'},
      {q:'¿Qué demuestra el texto sobre el conocimiento experto?', a:'Que es valioso para delimitar posibilidades y poco fiable para asignarles probabilidades.'},
      {q:'¿Qué debería exigirse a los expertos?', a:'Escenarios con condiciones explícitas, en lugar de pronósticos cerrados.'}
    ]
  },
  {level:'C2', title:'论批判的德性与代价', topic:'思想与伦理', minutes:9,
    paragraphs:[
      {es:`Se elogia la crítica como virtud cívica y se la castiga en la práctica casi sin excepción. Esta contradicción no es un defecto del sistema: es el modo en que el sistema se sostiene, tolerando la crítica en abstracto y desincentivándola en concreto.`,
       zh:`批评被颂扬为公民德性，而在实践中几乎无一例外地遭到惩罚。这一矛盾不是制度的缺陷：它正是制度维系自身的方式——在抽象层面容忍批评，在具体层面上使其失去动力。`},
      {es:`Conviene distinguir tres cosas que el lenguaje corriente mezcla. La primera es discrepar: sostener que una decisión es equivocada. La segunda es obstruir: impedir que se tome. La tercera es deslegitimar: negar el derecho de quien decide a decidir. Las tres se confunden con provecho para quien quiere silenciar la primera.`,
       zh:`有必要区分日常语言混为一谈的三件事。第一是提出异议：主张某项决定是错的。第二是阻挠：阻止它被做出。第三是使之失去正当性：否认决策者有权决策。把三者混为一谈，对想要压制第一种的人有利。`},
      {es:`El argumento más común contra la crítica es que erosiona la confianza. La objeción es seria, pero se enuncia casi siempre al revés: la confianza pública no se destruye al airear los errores, sino al ocultarlos, porque lo que se descubre por filtraciones produce un daño muy superior al que habría producido la corrección voluntaria.`,
       zh:`反对批评最常见的论点是它侵蚀信任。这个反驳很严肃，但几乎总是被说反了：公共信任不是因公开错误而毁掉，而是因掩盖错误而毁掉，因为通过泄露被发现所造成的损害，远大于主动纠正本会造成的影响。`},
      {es:`Hay, además, un coste personal que rara vez se computa. Criticar exige disponer de un margen —económico, profesional, afectivo— que no todos tienen. Cuando se celebra la valentía de quien critica y no se examina quién puede permitírsela, se convierte una virtud en un privilegio disfrazado.`,
       zh:`此外还有一项很少被计算的个人代价。批评需要有一定的余地——经济的、职业的、情感上的——而并非人人都有。当人们赞颂批评者的勇气却不审视谁负担得起这种勇气时，就把一种德性变成了伪装的优待。`},
      {es:`De ahí que la pregunta pertinente no sea si la crítica es buena o mala, sino qué condiciones la hacen posible sin arruinar a quien la ejerce. Una sociedad que solo admite críticas de quienes no tienen nada que perder no está fomentando una virtud: está seleccionando a sus críticos por su vulnerabilidad.`,
       zh:`因此关键问题不是批评是好是坏，而是什么条件能让批评在不毁掉批评者的前提下成为可能。一个只接纳"无所可失者"的批评的社会，并不是在培养一种德性：它是在按脆弱程度筛选自己的批评者。`},
      {es:`Cabe replicar que toda institución necesita cierto grado de cohesión para funcionar, y que la crítica ilimitada la haría inviable. Es verdad, y por eso la cuestión es de dosificación y de procedimiento: no cuánta crítica tolerar, sino por qué cauces, con qué garantías y con qué obligación de respuesta.`,
       zh:`可以回应说，任何机构都需要一定程度的凝聚力才能运作，而无限制的批评会使其难以为继。这是事实，因此问题在于剂量与程序：不是能容忍多少批评，而是通过什么渠道、有何保障、以及回答的义务如何。`},
      {es:`Lo que ninguna institución puede permitirse es confundir la incomodidad con el daño. La primera es el precio de tener información; el segundo, la consecuencia de no tenerla.`,
       zh:`任何机构都无法承受的是把"不适"与"损害"混为一谈。前者是掌握信息的代价；后者是缺乏信息的后果。`}
    ],
    glossary:[
      {es:'elogiar', zh:'赞扬'},
      {es:'cívico', zh:'公民的'},
      {es:'desincentivar', zh:'使其失去动力'},
      {es:'discrepar', zh:'提出异议'},
      {es:'obstruir', zh:'阻挠'},
      {es:'deslegitimar', zh:'使失去正当性'},
      {es:'con provecho para', zh:'对……有利'},
      {es:'silenciar', zh:'压制'},
      {es:'erosionar', zh:'侵蚀'},
      {es:'enunciar', zh:'表述'},
      {es:'al revés', zh:'反了'},
      {es:'airear', zh:'公开、曝光'},
      {es:'la filtración', zh:'泄露'},
      {es:'computar', zh:'计算'},
      {es:'el margen', zh:'余地'},
      {es:'afectivo', zh:'情感上的'},
      {es:'el privilegio', zh:'优待、特权'},
      {es:'la vulnerabilidad', zh:'脆弱性'},
      {es:'la cohesión', zh:'凝聚力'},
      {es:'inviable', zh:'难以为继的'},
      {es:'la dosificación', zh:'剂量调配'},
      {es:'el cauce', zh:'渠道'}
    ],
    structures:[
      {es:`Se elogia la crítica como virtud cívica y se la castiga en la práctica casi sin excepción.`,
       note:`两处均为被动 se 结构。第二句的 la 是直接宾语代词，后置于 se（se la castiga），这是西班牙语代词的固定顺序。`},
      {es:`tolerando la crítica en abstracto y desincentivándola en concreto`,
       note:`两个副动词并列，作 el modo 的补语，说明方式。en abstracto / en concreto 形成对照。`},
      {es:`lo que se descubre por filtraciones produce un daño muy superior al que habría producido la corrección voluntaria`,
       note:`superior a ＝「大于」，al que ＝ a + el que，关系代词作 producir 的宾语；条件式完成时表未实现的可能性。`},
      {es:`Cuando se celebra la valentía de quien critica y no se examina quién puede permitírsela, se convierte una virtud en un privilegio.`,
       note:`convertir A en B ＝「把 A 变成 B」。quien critica 与 quién puede 的区别：前者为关系代词，后者为疑问词引入名词性从句。permitírsela 中的 se 指批评者，la 指 la valentía。`},
      {es:`no cuánta crítica tolerar, sino por qué cauces, con qué garantías y con qué obligación de respuesta`,
       note:`不定式 tolerar 前省略了 se puede；no… sino… 对比两种提问方式，全部为疑问词引导的间接疑问短语。`},
      {es:`Lo que ninguna institución puede permitirse es confundir la incomodidad con el daño.`,
       note:`lo que… es… 名词性关系从句作主语。confundir A con B ＝「把 A 与 B 混淆」。`}
    ],
    questions:[
      {q:'¿Qué contradicción señala el autor al comienzo?', a:'Que la crítica se elogia como virtud y se castiga en la práctica.'},
      {q:'¿Qué tres cosas distingue?', a:'Discrepar, obstruir y deslegitimar.'},
      {q:'¿Cómo se destruye la confianza pública según el texto?', a:'No al airear los errores, sino al ocultarlos.'},
      {q:'¿Por qué criticar es también un privilegio?', a:'Porque exige un margen económico, profesional y afectivo que no todos tienen.'},
      {q:'¿Qué pasa con una sociedad que solo admite críticas de quienes no tienen nada que perder?', a:'Que selecciona a sus críticos por su vulnerabilidad.'},
      {q:'¿Qué dos cosas no deben confundirse?', a:'La incomodidad y el daño.'}
    ]
  }
];

